INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p987852-ce201', 'stk-mr.cool', 'CE 201', 'info', '{"desc": "مادة الستاتيكا \" علم السكون \"\n\nالكورس\nممتع و مهم جدا للسيفيل و الميكانيكال و متطلب أساسي لكثير من الكورسات…\n\nكورس يختص بدراسة\n* القوى و العزوم على الأجسام الصلبة .\n* الإتزان في بعدين أو ثلاثة أبعاد .\n* تحليل القوى في الأعمدة و الهياكل .\n* تحليل قوى المقاومة لحركة الأجسام .\n* حساب قوى الإحتكاك بين السطوح .\n* تحديد مركز الكتلة للأجسام .\n\nالكتاب\n\" Static Engineering Mechanics by Hibbeler 12th edition \"\nكتاب رائع جدا ،، مليء بالأمثلة و التمارين و يعطيك الزبدة من الدرس و مزود برسومات لكل سؤال.\n\nالكورس مهم جدا و لا يمكن تكمل في الهندسة المدنية أو الميكانيكية إلا وأنت معدي هذا الكورس و فاهمه تمام .\nالكورس مفيد من الناحية التطبيقية و يعتبر بداية للكورسات الي بعده كـ \" CE 203 , ME 201 \" …\n\nأفضل من يدرس الكورس في السمستر 112 ::\nحسين القحطاني\nمصطفى المنديل\n…\n\nنصيحتي لك عند مذاكرة الكورس ::\nنزل المانيول سلوشن للكتاب و حل أسئلة على كل شابتر (حل قد ما تقدر ) و إذا صعب عليك حاجة شوف المانيول سلوشن … الكورس كله مسائل و على قد ما تحل تبدع في الاختبارات …\n\nأتمنى أن أكون أفدت … مع تمنياتي للجميع بالتوفيق. 🌹 🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ce-201-statics/120666/2", "user": "Mr.Cool", "ts": 1329433862000, "tid": 120666, "pn": 2}}', 1329433862000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1004310-ce201', 'stk-menoo', 'CE 201', 'info', '{"desc": "^^ اضافه …\nالاولد اكزامز بالفاينل تنفع كثير … + الهانداوتس اللي يوزعها المنديل لطلابه …\n\nميجر ون سهل بس غالباً يكون تركات كثيره فيه … فركز …\nميجر 2 متوسط بس مباشر …\nالفاينل متوسط مائل للسهولة …\n\nالماده تحتاج للسرعه بالتفكير والحل …\nلأن غالباً الاسئله حلها طويل والوقت ما يكفي …", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ce-201-statics/120666/3", "user": "Menoo", "ts": 1331387261000, "tid": 120666, "pn": 3}}', 1331387261000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1047373-ce201', 'stk-user5470', 'CE 201', 'info', '{"desc": "جودة المقرر بشكل عام\n\nممتازة\n\nالمواضيع التي يغطيها المقرر\n\nفيكتورز + تحليل القوى المؤثرة على الجسم\n\nالكتاب المستخدم للمقرر\n\nممتع هالكتاب …هبلر ما قصر…\n\nالأسئلة والأمثلة المستخدمة في المقرر\n\nجدا كافية وممتعة\n\nمدى فائدته في الناحية التطبيقية\n\nههههههههه والله له فايدة بالفلسفة مع اخويائك اللي ما درسوا هالكورس 😛", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ce-201-statics/120666/7", "user": "user5470", "ts": 1338282518000, "tid": 120666, "pn": 7}}', 1338282518000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1171876-ce201', 'stk-s2010xxxxx', 'CE 201', 'info', '{"desc": "جودة المقرر بشكل عام: ممتاز\nالمواضيع التي يغطيها المقرر:التوازن و القوى والاحتكاك والفكتورز\nالكتاب المستخدم للمقرر: ممتاز جدا 👍\nالأسئلة والأمثلة المستخدمة في المقرر:مفيده للغايه\nمدى فائدته في الناحية التطبيقية:كل شي تدرسه بهالكورس ممكن تتخيله بحياتك العمليه\nاضافه: الكورس ممتع وشيق وما فيه حفظ , يعتمد على الفهم بشكل كبير, يمديك تجيب فيها قريد اذا فهمت كويس", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ce-201-statics/120666/9", "user": "s2010xxxxx", "ts": 1359387935000, "tid": 120666, "pn": 9}}', 1359387935000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1198573-ce201', 'stk-chemist', 'CE 201', 'info', '{"desc": "جودة المقرر بشكل عام:\nممتاز جدا للمهندس المدني ولا أرى أي ترابط بينه وبين المهندس الكيميائي 😞\n\nالمواضيع التي يغطيها المقرر:\n1) تعريف المتجهات والعمليات عليها\n2) اتزان القوى في الأجسام الساكنه (2D & 3D )\n3) العزوم في الأجسام الساكنه\n4) Trosses And Frames\n5) Friction\n6) تحديد مركز الأجسام الساكنه\n\nالكتاب المستخدم للمقرر:\nممتاز جدا من أفضل الكتب اللي مرت علي بالجامعة سردا وأمثلة وتوضيحا 👍\n\nمدى فائدته في الناحية التطبيقية:\nنفس معضلة EE 204 لا أرى ترابط بينه وبين الهندسة الكيميائية 😞 بس زيادة عدد للكورسات علشان نوصل 133 ساعة 🤠", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ce-201-statics/120666/10", "user": "Chemist", "ts": 1363051988000, "tid": 120666, "pn": 10}}', 1363051988000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1319865-ce201', 'stk-abo_yazeed6', 'CE 201', 'info', '{"desc": "مادة جميلة وسهلة و أقدر أقول أنه أكثر كورس ممتع أخذته لحد الآن\n\nحل fundemental problems كاملة وأسئلة الهومورك ومهم جدا تشوف الأولد اقزامز لأنه الأسئلة دائما لها نفس الطريقة\n\nميجر 1 سهل جدا لا تضيعه\nميجر 2 تقدر تقول أنه الأصعب,أصعب حتى من الفاينل لأنه المواضيع الي يغطيها بشكل عام تحتاج تركيز وانتباه “بشكل عام يتكلم عن مواضيع ال moment”\n\nالفاينل اختبارنا كان سهل جدا بل تافه والمواضيع الي يغطيها قليلة كلها كم سكشن لكن مهم أنك تحل أسئلة كثيرة لأنك تحتاج تكون سريع وغلطة وحدة ممكن تخرب عليك كامل السؤال لكن أعيد وأكرر أنها مواضيع سهلة بس تحتاج الانتباه,طبعا ما فيه أولد اقزامز للفاينل لذا حل أكبر عدد ممكن من أسئلة الكتاب", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ce-201-statics/120666/17", "user": "abo_yazeed6", "ts": 1389861984000, "tid": 120666, "pn": 17}}', 1389861984000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1370047-ce201', 'stk-ahmad-ali', 'CE 201', 'info', '{"desc": "المادة ممتعة جداً وسهلة الى متوسطة مو صعبة\nتحتاج منك انك تفهمها صح والكتاب ممتاز ومفيد جداً\nانتبه مع الدكتور واقرأ اكزامبلز الكتاب وافهم كل حرف بطريقة الحل ( الاكزامبلز قليلة وطريقة حلها والشرح ممتازة) اذا اشكل عليك اي درس حل اكبر عدد تقدر عليه من البروبلمز وبتفهمه 100% طبعا متوفر سوليوشن للكتاب في الانترنت\nبهذه الطريقة تضمن a+ ان شاء الله\n\nبالنسبة للاختبارات :\n\nميجر 1 (20 درجة)\nشابترين فقط (2+3) اسهل شابترين بالتالي لا تضيع الميجر\n\nميجر 2 (25 درجة)\nمواضيعه تعتبر اصعب من ميجر 1 وتغطي 3 شباتر (4+5+6) وشابتر 6 مهم جداً انك تفهمه لانه مشمول بالفاينل\n\nالفاينل (35 درجة)\nيغطي 5 شباتر ( 6+7+8+9+10) اخر شابترين عبارة عن جداول فقط تتبع طريقة معينة بالحل والباقي جمع وطرح\nشابتر 6 و 7 مترابطين ويحتاجو تدريب شوي\nشابتر 8 هو الاصعب بالمنهج واسئلة الفاينل اكزام على هذا الشابتر ما اشوفها مشابهة لاسئلة الكتاب للاسف\nوالمشكلة الاكبر بالفاينل ما في اولد اكزامز محلولة\n\nبرأيي الشخصي مادة الفاينل هي الاصعب فحاول لا تضيع اي درجة في المياجر\n\nالهومورك ( 5 درجات) على كل نهاية شابتر تقريباً 10 اسئلة ( تاخذ منك تقريباً 3 ساعات )\n\nالكويزات عليهم 10 درجات والحضور 5", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ce-201-statics/120666/21", "user": "ahmad-ali", "ts": 1400865555000, "tid": 120666, "pn": 21}}', 1400865555000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1508985-ce201', 'stk-ahm2d1', 'CE 201', 'info', '{"desc": "Term 182 :\n\nالكورس سهل بشكل عام بس فيه كم شابتر زي ٦ و ٨ فيها افكار جامده بقوه والباقي بسيط.\nدروس ميجر ١ - سهله مره -\nشابتر ١ - ٣\nدروس ميجر ٢ - وسط\nشابتر ٤ - ٦\nشابتر ٦ الي صعب الباقي سهل\nدروس الفاينل\nشابتر ٧-١٠\nشابتر ٨ الي صعب الباقي سهل", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ce-201-statics/120666/32", "user": "Ahm2d1", "ts": 1556231866000, "tid": 120666, "pn": 32}}', 1556231866000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p707726-ce201', 'stk-imported_broken_hear', 'CE 201', 'info', '{"desc": "هو شوف علشان ال che201 كومون صعب جدا بل اشبه بالمستحيل انك تغير يوم الميجر حقها … لكن انا ما ادري عن الـ ce201 اذا هي كومون برضو صعب انك تغير يومها ولكن اذا لا فعاد انت وشطارتك مع الدكتور حاول تجيبها معه بأسلوب كثير دكاترة يغيرون تواريخ المياجر عشان طالب او طالبين صاير لهم تعرض … اما اذا المادتين كلها كومون فهي وحدة من الثنتين يا ان دكتور الكيميكال يخليك تختبر قبل بنص ساعة او دكتور السيفيل تجلس نص ساعة زيادة عن الطلاب بحكم ان عندك قبلها ميجر … فالموضوع سهالات لاتشيل هم…راجع الدكتورين ومسهلة بإذن الله", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ce201-che201/95320/9", "user": "imported_BrOkEn_HeAr", "ts": 1285524913000, "tid": 95320, "pn": 9}}', 1285524913000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p517248-ce201', 'stk-user2967', 'CE 201', 'info', '{"desc": "اهلين\n\nادرسها الان\nانا اعتبرها سهله وفي بعض الفصول تصل للمتوسط\n\nكل اختبار يحتوي ع 3 الى 4 فصول\nالفاينل فقط تختبر ع اللي مااخذته بالاختبارات الفصليه >>> نقلا من شخص اخذها قبلي بخصوص كلامي للفاينل\nللمعلومية المادة كومن عامة 🙂\n\nخذها وتوكل ع ربك\n\nالمدرسين ع حسب ماسمع\nal-farabi sharif\nrashid allayla\nmostafa al-mandeel >> ادرس عنده الان روووعه في شررحه بس يعيبه كل اسبوع كويز وهوم وورك \"الله يخلي السليوشن مانيول 🙂\n\nالباقين بعضهم سئ وبعضهم ماعرفه\n\nاتامل اكون اني افدتك 🙂", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ce201/81797/2", "user": "user2967", "ts": 1262725246000, "tid": 81797, "pn": 2}}', 1262725246000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p724746-ce201', 'stk-eng.ammar', 'CE 201', 'info', '{"desc": "المادة من المواد اللي ما يبغالها مذاكرة و مهي صعبة\nبس افهم القانون و طنش الكتاب و حل مسااااااااااااااااااااااااااااااااااااااااااااااااااااااائل كتير\nلو فهمت الكتاب كله حرف حرف و ما حليت مسائل محتجيب جريد\nامسك مسائل الكتاب و حل في التمارين قد ما تقدر", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ce201/97045/4", "user": "Eng.Ammar", "ts": 1287649171000, "tid": 97045, "pn": 4}}', 1287649171000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p153215-ce201', 'stk-user1599', 'CE 201', 'info', '{"desc": "السلام عليكم\n\nمرحباً اخوي طفش\n\nشف انا ابتكلم لك عن اللي اعرفهم\n\nAL-GAHTAN\n\nاذا هو حسين القحطآني << the chairman\n\nالشرح يعني لك عليه , الميآجر سهله , وكذلك الفآينل\nومتسآهل ايضاً بالتصحيح\n\nلكن ما يعيبه انه المعدل دآيم مرتفع عنده\n\nفي الاخير تطلع بدرجه ما تعجبك , وفيه كم واحد يشتكي منه\n\n…\n\nAL-GHAMDI\n\nانحشششش عنه لا تقرررب ابد …\n\n…\n\nAL-MANDEE\n\nالشررررح ممتآز مآ عليه كلام\n\nتطلع وانت فآهم ,\n\nلكن اسئلته شويه صعبه ,\nبس اذا شديت حيلك تجيب درجه حلوة بإذن الله\n\n…\n\nALLAYLA R\n\nالليلاا\n\nهذا الدكتور فيه نآس مدحوهـ\n\nواعرف كم واحد جاب عندهـ +A\n\n…\n\nعلى العموم المآدهـ بإذن الله سهله …\n\nوالله يوفقك …", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ce201/54829/3", "user": "user1599", "ts": 1171873098000, "tid": 54829, "pn": 3}}', 1171873098000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p765149-ce201', 'stk-user4636', 'CE 201', 'info', '{"desc": "ههههههههههههههههههههههههههههه\n\nعبدالحميد الطيب\n\nانا عنده ياعزيزي لاتسمع لأي كلمه يقولها 🙂\n\nياخي شارح لنا 7.3 وهو مو بالسيلابوس اصلا!!!\n\nدور لك احد عند المنديل لبا قلبه واسأله وشف وش يقول لك بيعطيك كل شي يشيخ يسهل لك كل شي\n\nالماتيريال عندك شابترر 6 بس الفريمز\n\nشابتر 7.1 و 7.2\n\nشابتر 8 حق الفركشن ((اللي هي صناديق وماصناديق مدري وشو))\n\nشابتر 9\\ 9.1 , 9.2 , وبالسيلابوس موجود 9.3 لكن واحد عند المنديل يقول اصلا ماشرحه لنا بس مادري تأكد انت مابي افتي من عندي واورطك تدعي علي بعدين :s\n\nشابتر 10 الانيرشيا للإيريا وللفوليوم\n\nومثل ماقلت لك اسأل اي واحد عند المنديل واذا ماتعرف احد رح للمنديل بنفسه واسأله صدقني بيفيدك\n\nوبالتوفيق لي ولك >>> الى الان لازم يجيب فوق ال50 عشان ينجح بهالماده 😭", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ce201/100639/4", "user": "user4636", "ts": 1295277689000, "tid": 100639, "pn": 4}}', 1295277689000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p976219-ce201', 'stk-user5800', 'CE 201', 'info', '{"desc": "اخذت هالمادة السمستر اللي راح والحمد لله عديت بقريد طيب .\nالمهم ، المادة هذه بحاجة الى انك تحل واجباتك بنفسك .\nحل واجباتك بنفسك هي الركيزة الاساسية لفهم المادة .\nما فيه مشكلة تاخذ الحل من المانيول سلوشن ، لكن افهم السؤال اول شئ\nو حل سؤال ثاني مشابه ، للتاكد من الفهم ، وقارن حلك .\n\nاذا انت عند المنديل ، فلا تخاف .\nلان المنديل يوجهك صوب الجريدات العالية بالشرح و الهاند اوت و مسائل الواجبات\nاللي يختارها بعناية واللي تكون افكارها من افكار المياجر والفاينل ،، وبالتالي يعطيك حقك .\nواما اذا عند الطيب ، فالله يعينك على الشرح … لكن يقولون انه كريم في الجريدات .\n\nنقطة اخيرة .\nانا شفت ، ولا زلت اشوف ان ميجر 1\nاصعب وبقوة ، من ميجر 2 و الفاينل .\n\nميجر 1 افكاره متشعبة كثير ، فانتبه لها الشئ .\nلكن هذا لا يعني ان تهمل مذاكرة ميجر 2 و الفاينل بحجة السهولة النسبية بالمقارنة مع ميجر 1 .\n\nوآسف على الاطالة .", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ce201/118956/5", "user": "user5800", "ts": 1327870952000, "tid": 118956, "pn": 5}}', 1327870952000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1026707-ce201', 'stk-user6441', 'CE 201', 'info', '{"desc": "نعم\n\nالse اسهل بكثيييير من الce\n\nالse من سهولتها الافرج يعدي بال85 % >>> افرجنا الميجر الاول 87%\nوبعض الدكاتره يخلوها ستاندرد لان افرجها عااالي\n\nبس مو يعني تهملها الى وقت الميجر\nيعني يبيلها متابعه مع الدكتور وتفهم معه لان كتابها غبي ما تقدر تطلع منه بشي\nوالسلايدات الرسميه للماده ما هي واضحه والامثله فيها قليله مرره.\n\nبالتوفيق", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/stat-319-ce-201/124474/10", "user": "user6441", "ts": 1335089838000, "tid": 124474, "pn": 10}}', 1335089838000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p766043-ce201', 'stk-once_a_red', 'CE 201', 'info', '{"desc": "الماده خوفونا فيها وصعبه ومشابهه للفيزيكس 101\nومابعرف ايش\nونتيجة لهالتحذيرات الواحد يخاف وغصب يجيب العيد\nلكن وخذها مني يالطيب انا من جماعة الوارنينق تو يعني على قد حالي\nواشوفها حلوه وممتعه وسهالات وشكلي بطمح للـ a او b+\nانا عند الدكتور حسين القحطاني ممتع وطيب وهوموركاته فيها افكار وفيها فايده كونها 80% او اكثر تشبه الاختبارات\nوبس … ولك نصيحه لا تاخذ لاخير ولا شر مننا لان بعضنا يصدق وبعضنا لا\nوصعب تحدد مين الصادق ومين …", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ce-201/100816/5", "user": "ONCE_A_RED", "ts": 1295366849000, "tid": 100816, "pn": 5}}', 1295366849000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p770305-ce201', 'stk-mesh3l_al7arbi', 'CE 201', 'info', '{"desc": "السؤال الاول : سهل لكن يبغاله تركييييييييييييييييييييز … بلص تقلبه ماينص … راحت عليك\nالسؤال الثاني : اضن كان حق اللود والمومنتم على اليمين … هذا لو سلم من المومنتم اللي كانت عاليمين كان ضبطنا … لكن حست صراحة فيه\nالسؤال الثالث : تبع الفركشن … صراحة اممم … الحل طلع عندي نص صفحة بس … وانا اختباري بمبنى 10 … يوم شفت ورقت اللي قدامي لا والله مفلل الصفحة … قلت ياحبيبي حلي شكله خطأ هع هع\nالسؤال الرابع : centerodial << خلصت الكورس وانا ماعرف السبيللينق حقه … المهم هذا اممم خبصت بالقانون حقه … مع انه اسهل سؤال صراحة .\nالسؤال الخامس : المومنت اوف اينريشيا … هذا جلست اطالع فيه … واطالع فيه … واطالع فيه … واطالع فيه … واطالع فييه … واطالع فيه … واطالع فيه … وبعدها طالعت فيه … وبعدين جلست شوي ورجعت طالعت فيه … وطالعت فيه … وتذكرت الاجابة … لكن لخبطت بالاخير خخخخخ لكن يعتبر سهل نوعا ما …\n\nبشكل عام … حاسنا وقت الاختبار … ولا لو ذاكرنا صح كان حلينا … لكن وش حيلة اللي طالع من ماث 201 الساعة 10 ونص البارحة وعلى الغرفة وعلى كتاب الستاتيكس إلى الساعة ستة ونص وبعدها ع الاختبار … !!\n\nالله يستر … اول نقول نبغى الـ A وبعد ميجر ون نقول نبغى الـ B وبعد ميجر تو نقول نبغى الـC وبعد الفاينال نقول نبغى الـ D\nآآآآآآآآآآآآآآآآآآهـ\nKFUPM, THAT’S ENOUGH 😦 PLZ", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ce-201-final-exam/101212/2", "user": "Mesh3l_Al7arbi", "ts": 1295778955000, "tid": 101212, "pn": 2}}', 1295778955000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1364330-ce201', 'stk-tyer_shalwa', 'CE 201', 'info', '{"desc": "والله مدري على خبري قبل سمسترين المدرس ممتاز ولو رجع فيني الوقت بنزل عنده صح أنك تمل معه شوي وممكن تنام بس مب سيء أبداً\n\nوعلى فكرة المادة سهلة وكتابها من الكتب القليلة بالجامعة اللي كنت أذاكر منه\nبدون إستعانة بأي نوت\n\nيعني حتى لو أنت عند أسوء مدرس أفتح الكتاب بسيط شرحه وإكزامبل على كل شيء\nوبالتوفيق 🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ce-201/160877/5", "user": "Tyer_Shalwa", "ts": 1399983588000, "tid": 160877, "pn": 5}}', 1399983588000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p263868-ce201', 'stk-user2454', 'CE 201', 'info', '{"desc": "SHAMSHAD AHMAD\n\nهذا خذ معه و أنت مغمض … دكتور هندي شرييييييييييييييييح تفهم معاه بالراحة … لكن كريييف هوموركات ومياجره من النوت اللي يشرحه … لو تجتهد معه وتفهم … تطلع بقريد و أنت مرتاح\n\nNASER A. AL-SHAYEA\n\nهذا نصيحة لا تقربه … شرحه ممل تحس إنه يسولف مع نفسه … يالله يالله تسمع صوته\n\nMOSTAFA Y. AL-MANDEEL\n\nهذا شرحه لا باس به … أنا خذيت معه كورس من مدح الشباب هنا له … لكن تمنيت إني ما درست عنده\nيشرح لك لأشياء السهلة وتحس إن الكورس حلو وإنك ضامن القريد … لكن يجيب لك مياجر وفاينل تجلس تحوووووس فيها الين تتعب\n\n. AL-TAYYIB\n\nالطيب … يقولون طيب … ما أدري\n\nSHUKRI H. AL-SENAN\n\nهذا تخصصه هندسة طرق … عشان كذا ماله في ce 201 … حتى في تخصصه شرحه مش ولا بد\n\nRASHID I. ALLAYLA\n\nما يدري وين الله حاطه في الشرح … بس طيب ويدف قريدات بالهبل … تبغى تاخذ الكورس بس ماتفهم لكن تحصل قريد … خذ معه\n\nهذا اللي اعرف عنهم\n\nالباقين ما عندي اي خلفية عنهم\n\nأتمنى أكون ساعدتك", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ce201-081/62825/2", "user": "user2454", "ts": 1209947349000, "tid": 62825, "pn": 2}}', 1209947349000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p100095-ce201', 'stk-user786', 'CE 201', 'info', '{"desc": "اذا ما حصل القحطاني فانا انصحكم بالفارابي شريف\n\nمافي كويزات\n\nشرح ممتاز\n\nيكرف هومووركات حاله كأي دكتور\n\nمياجره حلوه ( ميجر 1 تافه وميجر 2 فيه مسألة وحده صعبه والفاينل اسهل من المياجر )\n\nبقى الفاينل قريد\n\nحتى لو اني لا سمح الله ما جبت قريد فانا لن انصح الا به لاني جربته", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ce-201-052/49157/6", "user": "user786", "ts": 1149547663000, "tid": 49157, "pn": 6}}', 1149547663000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p894120-ce201', 'stk-_hlali', 'CE 201', 'info', '{"desc": "الماده يبغى لها حل مسائل وتركيز مع الدكتور والماده اذا تابعتها اول\n\nبأول راح تكون ممتعه جدا جدا جدا وممكن اصعب تشابتر فيها الي هو\n\nشابتر 8 وشابتر 6 ومو ذيك الصعوبه بعد لكن انتبه انتبه تجيب العيد في\n\nميجر 1 لانه اسهل ميجر والافرج في الغالب ماينزل تحت 65 والطلاب في\n\nالغالب يبدعون فيه ويجيبون العيد في الميجر الثاني لدرجه ان الهايست\n\nفي كلاسنا كان 55 والي اشوفه ان الي يصححون الاوراق يكونون مو متساهلين\n\nفي ميجر 2 ايش السبب والله ماأدري مع انك تطلع من الاختبار وتحس انك 🤴\n\nكويس بس بعد ماتشوف الدرجه 🤪 .\n\nاما بالنسبه للي يسأل عن عريف زمان المدرس هذا حبوب بشكل مو طبيعي\n\nويرحب فيك بالاوفيس لو يشرح لك شابتر كامل ماعنده مشكله لكن …\n\nاقسم بالله لو انه يشرح لي من اليوم لين بكره ماراح افهم منه شي نهائيا\n\nلدرجة ان 8 في كلاسنا اخذوا f عنده والتحضير يحضر بورقه ولا يشيك بعدها ولا يدقق\n\nفي التأخير ولا عنده دي ان انا وصلت 16 غياب ولا قالي شي بس قعد ينصحني ويقول\n\nلي لو انك عند مدرس ثاني كان اخذت دي ان فيعني حاول تدور افضل من هالدكتور .\n\nوسلامتكم 🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ce201/111266/13", "user": "_HLALI", "ts": 1314964023000, "tid": 111266, "pn": 13}}', 1314964023000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p263283-ce201', 'stk-_legend', 'CE 201', 'info', '{"desc": "في عندك خيارات اخرى اخوي :\nماث 201 عندك الجبيلي و ميموني مثلاً …\nce 201 عندك شمشاد او الليلا او بدر\n\nانا الحين اخذ الماث مع الجبيلي , و حقيقة اول مرة احس انه حصة الماث فيها متعة , و انصح به بقوة\nو السي اي مع شمشاد , الاستاذ ممتاز كويس , لكن ينعس حبتين … مدري هو مني او منه بحكم انه اول كلاس الصبح …\n\nلكن حسب قائمتك :\n\nاليوسف : حسب كلام الشباب انه ممتاز , و يتشكرون فيه … اعتقد احسن الخيارات\n\nالمنديل : هو التوب بالشرح حقيقة بها الكورس , لكن اختباراته يقولون صعبة و يبي لك تتعب علشان القريد … لكن الشرح توب التوب , حضرت معه كلاسين … ما اتوقع فيه احسن من كذا\nو سب كلام الشباب يقولون انه يقول ن اول كلاس : \" ثلاثة منكم بياخذون A و ثلاثة بياخذون F \"\n\nاما السنان و الغامدي و عيبان لا تقربهم ابد … بالاخص الغامدي , الورس يكون انواع القلق و الهوموورك تعجيزي , اما السنان اخلاق لك عليه , عيبان مو حق تدريس …\nو الخيار لك", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ce-201-201/62936/2", "user": "_legend", "ts": 1209756016000, "tid": 62936, "pn": 2}}', 1209756016000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p359697-ce201', 'stk-top-boy', 'CE 201', 'info', '{"desc": "انا مع المنديل ( الكوارديناتور حق الماده ) يقول انه بيحسب اعلى و اقل درجة وبناء عليهم بيحط الدرجات\n\nبالنسبه للماتيريل اللي اعرفه ان شابتر 2 و 3 محذوفه\n\nوان الشباتر الاخيره اللي مادخلت في الميجر 2 راح يكون عليها 70% من الاختبار\n\nطبعا في شابتر 6 على ما اعتقد الل Trusses محذوفه يعني المطلوب هو Frame\n\nو كمان فيه سؤال عن Equilibrium in 3D فقط يعني 2D مو مطلوب\n\nهذا اللي اعرفه وانشاء اني اكون افدتكم وما نسيت شيء\n\nعلى فكرة تقدر تتأكد اكثر من بقية الطلاب\n\nلا تحرمنا من الدعاء\n\nبالتوفيق", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ce201/70024/5", "user": "Top-Boy", "ts": 1233591128000, "tid": 70024, "pn": 5}}', 1233591128000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p359846-ce201', 'stk-user3545', 'CE 201', 'info', '{"desc": "انا كنت عند المنديل يوم السبت في الاوفس وقال الكلام هذا :\nCh1 مو داخل في الاختبار\nCh2 مو داخل في الاختبار\nCh3 داخل في الاختبار ومنه سؤال عند 3-d\nCh4 مو داخل في الاحتبار ( بس هذا شابتر خدمات يعني راح تستخدمه بس ما راح تسئل عنه بالتحديد)\nCh5 مو داخل بالاختبار (يقول ان اساس هالكورس ) ما فيه تعارض انت لازم تستخدمه في بعض الاسئلة\nCh6 داخل معنا ومنه الفريم والترس مو داخل\nCh 7 داخل معنا في الاختبار\nCh8 داخل معنا في الاختبار\nCh9 معنا في الاختبار وبنسبة 90 % راح يكون عن السنترويد اوف ماس\nCh10 معنا في الاختبار", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ce201/70024/13", "user": "user3545", "ts": 1233607063000, "tid": 70024, "pn": 13}}', 1233607063000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p199507-ce201', 'stk-user2063', 'CE 201', 'info', '{"desc": "والله يالطيب انا اخذت مهاه\n\nالصراحه شرح من جنبها حتى انه ما اتذكر مسك الطبشير الا مراة معدوده طوال الترم\n\nكل شرحة عبارة عن امثلة الكتاب موجوده على بور بوينت ويقراء المثال ويقراء الاجوبه وبس\nواحيانا المحاضرة تكون 35 دقيقه بس\nواحيانا المحاضرة كلها\n\nالصراحه الماده اكثر من سهله لانها تعتبر اساس لمواد الهندسه المدنيه\n\nفاذا تبغا تفهم لاتاخذ معاه\nشوف اذا في الصويان او المنديل نزل معاهم\nواذا مافي الله يعينك انزل عنده\n\nوبالتوفيق يارب", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ce201/58065/2", "user": "user2063", "ts": 1188965222000, "tid": 58065, "pn": 2}}', 1188965222000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p74872-ce201', 'stk-user1186', 'CE 201', 'info', '{"desc": "ابشر بالمساعدة\n\nالمادة ممتعة وماهي صعبة بس تحتاج مذاكرة لأن قوانينها كثير وتتكلم عن تحليل القوى وكيف تحسب الفورسيز والمومنت وشغلات ثانية زي الفكتورز\n\nاما بالنسبة للصيف احس انها ماهي ثقيلة بس تحتاج متابعة وحل هموركات والظاهر لها سليوشن منتشر\n\nاتمنى لكم + A\n\nتحياتي\nالمتألق", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ce201/36576/3", "user": "user1186", "ts": 1115203384000, "tid": 36576, "pn": 3}}', 1115203384000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p725390-ce201', 'stk-mohammad.as', 'CE 201', 'info', '{"desc": "شباب صعب الكتاب تحل مساءله كله يعني كل تشابترين تقريبا عليها اربعين سؤال…\nوفيه بعض الافكار جدا جدا معقده 3-22 و 3-23 صراحه مقعده بشككلل …\nلكن افضل شي اشوفه نذاكر واجبات الكوردنيتر والامثله اللي يركز عليها …\nيعني اللي يدرس عند الفرابي الظاهر هو الكوردنيتر او المنديل ما ادري اي واحد فيهم يريت يعلمنا\nعن الاشيا اللي يركز عليها …", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ce201/97107/9", "user": "mohammad.as", "ts": 1287751026000, "tid": 97107, "pn": 9}}', 1287751026000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p947599-ce201', 'stk-user6430', 'CE 201', 'info', '{"desc": "الميجر هذا كان سهلا جدا و لكن يحتاج وقت\nو هذا الشيء ليس بالغريب في جامعتنا الموقرة لأن الميجر إذا يكون سهل أعرفه أنهم بيعطونك وقت أقل من الوقت الذي تحتاجه لحله\nو إذا صار صعب يعطونك وقت أكثر لأنه مابتحل و لكن لكي عندما تقول صعب راح يرد عليك و يقول معك وقت طويل و إذا قلت الوقت مايكفي بيقولك الإختبار كان سهل مايحتاج كل الوقت الذي عندك\nفلا تعب نفسك", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/2-ce201/116255/7", "user": "user6430", "ts": 1323881766000, "tid": 116255, "pn": 7}}', 1323881766000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1398793-ce201', 'stk-a_dulaziz', 'CE 201', 'info', '{"desc": "المشكلة بأقل مجهود تختلف من شخص لشخص\n\nفي ناس بأقل مجهود تجيب b و ناس تجيب d بنفس كمية الدراسه\n\nالكتاب ما تحتاج فيه كونسبت عالي شي بسيط المهم المسائل\n\nحل لما تطفش\n\nأبدأ بالهومورك بعدها المسائل الي يحلها الدكتور بعدين شف المسائل الي تجي بالأولد أقزام و دور شي يشبها بالكتاب", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ce-201/165268/2", "user": "A_DULAZIZ", "ts": 1410202804000, "tid": 165268, "pn": 2}}', 1410202804000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p920884-ce201', 'stk-_004', 'CE 201', 'info', '{"desc": "Examples + Fundamentals + HomeWorks + أسئلة من الكتاب لو عندك وقت\nأظمن إنك ما تقل عن الـ B\nالميجر الثآني غالبا المتيريال حقه أصعب من الأول\nبس الفااااينل سسسسسسسسسسهل جدا من الاول والثاني\nلاحقوا طلاب المنديل ترا يعطي هينت دايم عن الإختبار\nوالماده سهالات", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ce-201/114021/3", "user": "_004", "ts": 1318875954000, "tid": 114021, "pn": 3}}', 1318875954000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p265361-ce201', 'stk-gahtani', 'CE 201', 'info', '{"desc": "اخوي بالنسبه للطيب انا اخذت عنده كورس\nشف الدكتور ما عنده افرج درجاته ستنادرد\nيعني تجيب 69 تاخذ D+\nتجيب 84 تاخذ B\nتجيب 94 تاخذ A\n\nبس احسن حاجه في الدكتور انك تضمن درجات الهومورك والكوزات كامله\nلانه كل حصه يشرح الدرس واذا خلص يعطيك كوز ويبدا يحل الكوز وانت تنقل الجواب وبعدها تسلمه الورقه\nلكن مساله قريدات عنده للاسف مافيه لانها ستنادرد", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ce201-081/62825/3", "user": "gahtani", "ts": 1210501304000, "tid": 62825, "pn": 3}}', 1210501304000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p267628-ce201', 'stk-user1326', 'CE 201', 'info', '{"desc": "Abdul-hamid J. Al-tayyib\nدكتور ممتاز وشرحه ممتاز والمياجر من النوت … حتى في احد المياجر طلع الافرج 100 << دوافير السكشن ذا\nتطلع من الكورس بقريد كويس لكن المشكلة الكلاس حقه غثيييييييث\n\nShamshad Ahmad\nكررررريف بالذات الهومووركات واذا تبي تطلع من الكورس فاهم خذ عنده\n\nNaser A. Al-shayea\nبدون كلام طويل … ابعد عنه\n\nHamdan N. Alghamdi\nحمدان الغامدي هذا انا اخذت معاه نفس الكورس … اشررررررررد عنه ،، في الشرح داااج ويجيب اسئلة هوموورك من راسه واذا تاخرت عن الكلاس نص ثانية سجلك متاخر ومياجره متوسطة والقريد سيء جدا\n\nMostafa Y. Al-mandeel\nيشرح لك السهل ويخلي الصعب … كويزات فجائية … ومياجره توقع كل شي … بس يدف في القريد اذا كنت مجتهد معاه\n\nShukri H. Al-senan\nمو عارف وين الله حاطه\n\nSaad A. Aiban\nاشغاله كثيرة خاصة انه في مركز التوجية والارشاد … ولكن يفضل تبعد عنه\n\nRashid I. Allayla\nحبييييييب وطيبة قلب عليه ومتساهل كثير … مياجره من النوت ويدف في القريد\n\nباختصار اذا تبي تطلع في الكورس فاهم خذ عند احمد شمشاد واذا تبي تطلع بقريد خذ عند الطيب او راشد الليلا", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ce201-081/62825/4", "user": "user1326", "ts": 1211271470000, "tid": 62825, "pn": 4}}', 1211271470000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p900400-ce201', 'stk-omar.a', 'CE 201', 'info', '{"desc": "قال بيعطينا هومورك يوم الاربعاء هذا على المتيريال اللي غطاه خلال السبت والاثنين\n\nبالنسبة للكويزات والهوموركات … الكويزات عليها 10% والهوموركات عليها 5% من الكورس\n\nبالنسبة للي مكتوب في السيلابس … ان الهوموركات اسبوعية\n\nشرحة الى الآن ممتاز وممتع ويوصل لك المعلومة بأسهل طريقة\n\nطبعاً هو ماشي على السيلابس خلص ch1 ,ch2 : 2.1 & 2.2\n\nالسلايدات موجودة في صفحته الخاصة وشاملة للكورس كله\n\nhttp://faculty.kfupm.edu.sa/CE/almandil/\n\nعدا ذلك …قالنا الكورس ايزي وانجويبل …دونت ميس ات\n\n🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ce201/111953/2", "user": "Omar.a", "ts": 1315879150000, "tid": 111953, "pn": 2}}', 1315879150000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p727887-ce201', 'stk-kfupmss', 'CE 201', 'info', '{"desc": "الحمدالله على كل حال\n\nالاختباار ماكان سهلا ولا كان صعبا\n\nمتوقعة الاسئله بتكون كذا\n\nبس كان محتاج شوية تركيزز\n\nحتى نوعية الاسئله تتكرر\n\nيعني ماجابلك if the maximum force it can reach is …\n\nاو what is the minimum force…so that the distance will be …\n\nالاسئله كانت اوجد القوه او الزاويه\n\nيعني صراحا ماذاكرنا عدل\n\nبس يلا اللي راح راح وان شاءالله نحقق الاسيوية في المياجر الجايا\nقصدي نرفع درجتنا", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ce-201/97341/17", "user": "KFUPMss", "ts": 1288169067000, "tid": 97341, "pn": 17}}', 1288169067000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p594433-ce201', 'stk-user3725', 'CE 201', 'info', '{"desc": "شباب انا واحد من الناس اللي ما فهمت بهالمادة الا شي بسيط والمشكلة اني سينير ستيودنت مالها داعي اتاخر ترم عشان ماده\n\nالميجر الاول تحت الافرج\n\nالميجر الثاني بعد اسبوعين على شابتر 4 و5 و6\n\nوانا محتاج من تقوية في هالمادة\n\nاذا احد منكم يقدر يساعدني مقابل مبلغ مادي او يدلني على مدرس خصوصي لهالمادة اكون شاكر لكم", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ce-201/87218/1", "user": "user3725", "ts": 1272244778000, "tid": 87218, "pn": 1}}', 1272244778000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1086387-ce201', 'stk-_special_one', 'CE 201', 'info', '{"desc": "السلام عليكم\n\nانا اخذت الكورس بالصيف الماضي .\n\nالمادة بدايتها اعتماد كبييييييييييير على الاحداثيات و طريقة تمثيل الاجسام و تحليلها على هذي الاحداثيات\n\nبعدين تبدأ بالاهتمام بالجسور و المباني و ادوات ميكانيكية بسيطة و القوى المؤثرة عليها . و بتدرس انواع القوى ( الاحتكاك , العمودية , … )\n\nو اخيرا بتاخذ ال (moment of inertia ) و تحديد مركز الاجسام .\n\nالكورس بشكل عام متوسط الصعوبة 😎. ذاكر اول باول و بتمشي سلام سلام 🤠\n\nو نصيحححححححححة من مجرب حاول تبدع بالميجر الاول لانه الميجر الثاني عادة يكون اصعب بكثير لكنه مو مستحيل فاذا جبت بالميجرين درجة طيبة فاضمنلك الدرجة الطيبة لانه الفاينل موووووية 🤠\n\nاعذرونا عالاطالة …\n\nو جاهز لاي استفسار عندكم … ❤️ 🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ce-201/129804/6", "user": "_SpEcIaL_OnE", "ts": 1346693805000, "tid": 129804, "pn": 6}}', 1346693805000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1437578-ce201', 'stk-abdullah-1', 'CE 201', 'info', '{"desc": "CE 201\nالمادة من ناحية الفهم تعتبر سهلة جدآ.\nبشكل عام المادة تتكلم عن التوازن والسكون\nمتيريل الميجر الأول يعتبر هدية ( sigma F=0 )\nمتيريل الميجر الثاني يبي له مذاكرة شوي (مهوب صعب)\nمتيريل الفاينل سهل\n\nالقريد فيها سهل ويتحدد من درجة الميجر الثاني ( طبعا الاول لا تضيعه )\nA+ > 90\nالواجبات اسبوعية طويلة ( وهذا عيب المادة ) المانيول سليوشن قديم شوي (بعض الاسئلة ما تحصلها)\n\nعموما المادة سهلة وافكار الاسئلة نفسها كل ترم (old exams)", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ce-201/171426/4", "user": "abdullah-1", "ts": 1451582618000, "tid": 171426, "pn": 4}}', 1451582618000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1022809-ce201', 'stk-prince_97', 'CE 201', 'info', '{"desc": "السلام عليكمــ …\n\nأخواني أنا حاب اأستفسركم في مادة الـ ce 201 …\n\nيعني هل هي صعبة أو سهلة … ومن أفضل مدرس لها …\n\nوأي شيء ممكن يفيدني في هالمادة … خصوصا وأنه سيكون ثاني سمستر لي\nفي الفريشمان … وأنا محتار بينها وبين الـ إنجلش 102 …\n\nوبالتوفيق للجميع . … 🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ce-201/124286/1", "user": "prince_97", "ts": 1334495944000, "tid": 124286, "pn": 1}}', 1334495944000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p892521-ce201', 'stk-user5430', 'CE 201', 'info', '{"desc": "المادة تتكلم عن الدايركشن و فورسز\n\nالمادة ممتعة لو اخذتهآ عند دكتور ممتع ,\n\nانصحك بححححل الاسئلة بـ نهآمه 😆\n\nحل اسئلة الكتاب قد ما تقدر + اسئلة الواجب +\n\nفيه الدكتور الطيب ] يجيب لطلابه كل يوم سؤال يحلونه بورقة خارجيه حاول تاخذ هالسؤال منهم\n\nلكــــــــن لا تنزل عند هالدكتور 😆\n\nالله يوفقك 🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ce201/111266/6", "user": "user5430", "ts": 1314444171000, "tid": 111266, "pn": 6}}', 1314444171000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p892542-ce201', 'stk-user5712', 'CE 201', 'info', '{"desc": "+1\n\n-----------------------\nبالنسبة لمادة ce 201 أنا أشوفها مادة ممتعة ومذاكرتها حلوة\nلكن المياجر عادة تكون معقدة وفيها لف ودوران\n\nوأفضل طريقة أنك تتغلب على هالشغلة هي كثرة حل الأسئلة سواء من الكتاب أو الأولد إكزام\nوطبعاً كل ميجر تختبره انساه لأن الفاينل من نهاية الميجر الثاني إلى نهاية المنهج فقط (يعني مثل المياجر)", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ce201/111266/8", "user": "user5712", "ts": 1314446732000, "tid": 111266, "pn": 8}}', 1314446732000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p80052-ce201', 'stk-skfupm_a', 'CE 201', 'info', '{"desc": "دكتور جدا محترم\n\nراقي\n\nيقدر الطالب…\n\nشرح واضح …اختبارات سهلة للي متابع معه\n\nاختباراته مافيها فلسفة …مع انه لو بغى يتفلسف تفلسف\n\nاخذت معه CE 201\n\nدرجاته …حقك تأخذه\n\nلكن اكثر شي اذكره في هالمادة اني ما اذكر اني تعبت معاه\n\nبل كنت اشعر معه براحه بعكس بعض المدرسين اللي يخلي\n\nمن المادة التافههههههههه… مثل الفيزكس.\n\nالمياجر كنا نأخذها في الكلاس صباحا … مدتها 45 دقيقة\n\nوكانت ثلاث مياجر…\n\nلكن اذكر انه ما كان معطي اهمية للهوموركات خلال السمستر\n\nلدرجه يعطينه الارقام حق المسائل ولا يسأل عنها ولا يرجعها بعد التصحيح مما يوحي للطالب انها ماهي مهمة لكن في النهاية اعتبرها ووضع عليها (لود)\n\nماهو هين…\n\nواكلناها…\n\nتحياتي", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ce-201/47992/5", "user": "SKFUPM_A", "ts": 1126043570000, "tid": 47992, "pn": 5}}', 1126043570000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p765703-ce201', 'stk-hexane', 'CE 201', 'info', '{"desc": "بسراحة ما عندي خلفية عن قريد الأفرج و لكن زي ما هو موجود في السيلابس توزيع درجات المادة كالتالي :-\n\n- هوم ووركات ,كوزات ,حضور = 15%\n-الإختبار الأول = 20%\n-الإختبار الثاني = 25%\nالإختبار الأخير = 40%\n\nلاحظو إن الفاينل عليه 40% يعني تعتبر فرصة تعويض للطلاب 👍\n\nو لا تفكرون بدرجة النجاح و بس , كل واحد يسوي أفضل ما عنده لإنك سواء عرفت الأفرج قريد أو ماعرفت ما راح يقدم أو يأخر بل ممكن إنه يحبط الطالب أكثر\n\nأقول لكم هذا الكلام لأني مجرب\n\nبس إنتبهو من القلق أو المخاوف الناتجة من الشك بعدم القدرة على النجاح في هذا الكورس\nلأنها بتتعب الطالب و بتهد حيلة\n\nفكل واحد يحسن الظن بربه و يعطي المادة أفضل ما عنده بحسب قدرته و إستطاعته\nو يدعي ربه ,و يقول للوالدين يدعون له\n\nو بإذن الله راح يشوف اللي يسره 🙂", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ce201/100531/3", "user": "HeXaNe", "ts": 1295335891000, "tid": 100531, "pn": 3}}', 1295335891000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1075518-ce201', 'stk-user4389', 'CE 201', 'info', '{"desc": "انا درست معه ce201 وراح اذكر إيجابياته وسلبياته:\n\nالإيجابيات:\n1- الرجل اخلاق بشكل كبير .\n2- يسوي ميك اب كوز للفصل كامل اذا جابوا العيد في الكوز.(8 كوزات في الفصل)…\n3-يكتب في السبوره .\n4- اذا جيت تراجع معه للكوزات لازم يدفك اقل شيء درجتين .\n\nالسلبيات:\n1-ما ياخذ تمارين كثيره للشابتر.\n2-الهوم ورك عنده كثير كل واجب 10 الى 12 سؤال.\n3-شرحه متوسط (يعني لا تعتمد 100% عليه)\n\nبس نصيحه نزل معه لان الدكتور طيب جدا جدا و اذا على الشرح كتاب ce جيد جدا للمذاكره…سلام وبالتوفيق", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/shakhawat-chowdhury/95067/9", "user": "user4389", "ts": 1344050953000, "tid": 95067, "pn": 9}}', 1344050953000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1446677-ce201', 'stk-abdulrhmanof', 'CE 201', 'info', '{"desc": "أذا أنت من النوع اللي لازم يفهم من شرح الدكتور لا تنزل عنده\nمايشرح ابدا بس يقلب في السلايدات اللي هي من صفحات الكتاب ويقرأ\n\nوبالنسبة لce201 التصحيح كله عند القريدر وبشكل عام تصحيحاتهم متساهله جدا في الكويزات والمياجر\n\nce201 كتابه جمييل وينفهم منه الكونسبت والأمثله والأسئله ممتازه فيه لكن تحتاج تحل بنفسك مسائل كثثيييييييير عشان تبدع في الاختبارات", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/vohra/172965/5", "user": "ABDULRHMANOF", "ts": 1460656895000, "tid": 172965, "pn": 5}}', 1460656895000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1319085-ce201', 'stk-user7794', 'CE 201', 'info', '{"desc": "ce201 - 131\n\nالتحضير :\nنهاية كل كلاس…و نادرا بالبداية …\nمتساهل بالتحضير… واحد كان يستحق dn لكن ساعدة .\n\nطريقة الشرح :\nأممم … كان يشرح الكونسبت بالبداية و بعدين يحل مثال متوسط الصعوبة …\nشرحة كويس نوعا ما … لكن طبيعة المادة “ce201” تحتاج جهد شخصي في الفهم … و خيال واااااسع…\n\nالكويزات :\nسهلة و كثيــــــــــــــــــــــــــــــــــــــرة.\n\nالمياجر: كومن و كانت متوسطة الى صعبة …والوقت ليس كافي لغير الدوافير…\n\nالفاينلات : كومن … وكان سهل الى متوسط والوقت كاااافي 🙂\n\nالقريد النهائي: b\n\nالصوت: واضح\n\nإضافات :\n* تقييمي لسمستر 131 … وهو كان يقول انه رح يتغير بالأترام الجاية خصوصا بالتحضير.\n*بالنسبة للـce201 , المادة سهلة بس يبيلها جهد شويتين و أنصح الطلاب بالموقع تبع الكتاب رح تلاقيه بأول الصفحات…\n* الدكتور أخلاق …لكن أحيان يتنرفز لو سألته كثير .\n…\nكل التوفيق 🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/wael-m-al-haj-yaseen/148326/7", "user": "user7794", "ts": 1389704688000, "tid": 148326, "pn": 7}}', 1389704688000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1446539-ce201', 'stk-chelsea_17', 'CE 201', 'info', '{"desc": "قد نزلت نفس جدولك بالضبط ترم 153 وكان ممتاز ما عدا ce 201 بسبب الدكتور, المادة بالصيف تعتمد بشكل كامل على الدكتور وكان وقتها الملك.\n\nوالجيولوجي سهله لكن تعتمد برضو عالدكتور لأن كل دكتور له اختباراته الخاصة وتوزيع درجاته, وليد عبدالغني جربته وممتاز أما كيمينكسي يفيدونك طلابه( أو التقييم ان كان موجود ).\n\nبس 3 لابات ممكن تتعبك خاصة ان لهم لاب فاينل, 261 لابها عملي فما بتذاكر له واجد اما جيولوجي اذكر على ترمنا كان متعب ( كل لاب كويز وفيه فاينل وميدتيرم) و 215 ما اشوفه سهل لكن ولا وحدة من هاللابات فيها بروجكت فتعتبر مقبولة 3 لابات.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/161-153/172928/2", "user": "Chelsea_17", "ts": 1460516512000, "tid": 172928, "pn": 2}}', 1460516512000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p369937-ce201', 'stk-user5201', 'CE 201', 'info', '{"desc": "طيب بالنسبة لل ce 201\nماتقدر تعدل الدكتور\n\nشوف اي واحد ثاني\n\nترا سعد عيبان داج والمادة يبغالها واحد شريح\nلانه pure physics\n\nافضل الموجودين في ce 201\nالفارابي وشمشاد والمنديل\nوكلهم شرحاً كويسين\nمع ملاحظة ان مياجر المنديل ناار\nوالافرج حق كلاساته بالمياجر مايتجاوز 50 من 100 اطلااااااااااااقاً\nهذا بالنسبة لمياجر المنديل بالنسبة لمياجر شمشاد والفارابي فلا علم عنها اطلاقا\nولكن حط في بالك اولا واخيرا المادة يبغالها كرف لانها تلحوس المخ\nركز فيها قد ماتقدر والله يوفقك\n\nبالنسبة للماث فشودري جيد من ناحية الشرح\nاسلوبه يشدك له راح تحس بفرق بداية السمستر بس بعدها تتعود عليه\nممتاز حقيقة شودري واكتب نوت معه وركز في المادة\nوبهلولي حتى هو جيد ولو مانتبهت معه في شي او في جزئية وسرحت فيها ممكن تضيّع بعدها\nلانه تحس انه مستعجل وده يخلص الدرس في اسرع وقت لكن لما تركز معه مية المية راح تفهم\n\nو ics انا في نظري واعتقادي انهم كلهم داااااااااااااااااجين بالنسبة للدكتور اللي انذكر فوق مليح فما اعرف عنه\nلكن لو كان بلح موجود فهو افضل الموجود من السيئين\nلان ics 101 تحس انهم يرمون لها كل من هو داج ولا يدري عن امها …\n\nهذا اللي انا اعرفه واما الباقين فلا علم لي بهم اطلاقا\n\nوالله يوفقك اولا واخيرا ويكتب لك الخير مع هذولا الدكاترة", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/70712/7", "user": "user5201", "ts": 1235126665000, "tid": 70712, "pn": 7}}', 1235126665000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p966882-ce201', 'stk-amat_24', 'CE 201', 'info', '{"desc": "انا اشوف انك تاخذ ce201 بدري، لانه راح يفتحلك كورسين السمستر الجاي، وهي خطوة ممتازة\n\nومهما لعبت في الخطة، راح تلاقي كورسات مكنكل مفتوحة لانك سويت هذي الخطوة من بدري\nوضروري مررررة تاخذه لانك ناوي تاخر الكمستري يعني فيه كورس مكنكل حيتقفل عليك (ال216 وراه سلسلة طويلة من الكورسات اللي تفتح بعض)\nعلى الاقل لانك قيدت نفسك من ناحية الكمستري، حاول تشد ,وتتقدم من ناحية ثانية\nاذا اخذت الستاتكس ورسمت خطتك صح، تقدر ما تتاخر ابدا حتى بدون ما تاخذ صيف زيادة\nاقترح عليك انك تسوي فايل اكسل وتكتب فيه خطتك الين التخرج، ابدا بالخطة الرسمية، بعدين سوي التعديلات حقتك، حاول تتاكد من البري ركوزتس واعرضها على طالب جونير\\سينير\n\nبالنسبة للكورس ce201، الكورس 4 قوانين بس، يعتبر كورس مهارة\nيعني مافيه قراية وكثرة هرج\nهي كم قانون، بس لازم تعرف تستعملها صح\nلو تحل كل الاقزامبلز المحلولة اللي في الكتاب بنفسك، ما راح تتعب ابدا في الاختبارات واضمنلك 85%+ في كل اختبار بالراحة\nحتى الهوموورك، حله عشان درجته بس، مو عشان يساعدك في الاستعداد للاختبار\n\nبس عشان لا تدعي علي اذا سويتها 😁 :\nطير الICS ،خذ بدالها عربي\\اسلامي او حتى انقلش!\nالانقلش صحيح قروشة بس ترتاح ايام الاختبارات لانه ما يتطلب مذاكرة\n\nالفزكس والماث ما يبغالهم شي بس اغلب الفرشمن يفحطو فيهم (كورسين السمستر الثاني اصعب بكثير من الاول)، اتوقع السبب لانه الواحد ما تعود يذاكر لاكثر من مادتين جدية في نفس السمستر، وانا مقترح عليك تاخذ مادة ثالثة معاهم.\n\nبالتوفيق 🙂", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/118148/6", "user": "amat_24", "ts": 1326492655000, "tid": 118148, "pn": 6}}', 1326492655000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1259881-ce201', 'stk-user4626', 'CE 201', 'info', '{"desc": "الثيرمو الكتاب حقها جدا ممتاز بالنسبة للأمثلة و المسائل\nبالنسبة للتعاريف و المفاهيم ممكن تذاكر من اي سلايدات أتوقع في سلايدات حقت أحمد شاهين\n\nce201 كتابها جدا ممتاز و في له مانيول سليوشن و أحسن شي تسويه انك تفهم الامثلة و تحل الهومورك لحالك و لازم تذاكرها أول بأول و لا تتراكم عليك و قبل الميجر لازم تمر على الاولد اكزام لان القسم دايما يكرر الافكار\n\n210 مادة بالنسبة لي غثيثة لكنها مهمة جدا و راح تحتاجها قدام\nلازم تركز فيها مع الدكتور و تدرب على البرنامج كل يومين على الاقل ولو نص ساعة عشان تتعود عليه و حاول تبدع في المياجر لانها اسهل من الفاينل\n\nو دعواتي لك بالتوفيق", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/148976/2", "user": "user4626", "ts": 1378324157000, "tid": 148976, "pn": 2}}', 1378324157000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p834354-ce201', 'stk-user5643', 'CE 201', 'info', '{"desc": "انا أنصح انك تنزل ce201 + math\n\nبالنسبة للمادتين هذول لو أخذتهم بترم ، ماراح تجيب فيهم قريد مثل لما يكونون بالصيف\n\nدايم هالمادتين بالصيف سهالات وتمشي معاك زي العسسسسل\n\nهذا والله أعلم\n\nابي ااكد لكم على نقظه يا شباب\n\nلا تفوتوووووووون الce بالصيف ( الا اذا نزلها حمدان الغامدي او الرطرووط)\n\nبالاترام العاديه تكون كومن … وسلللللللللللللللخ سئله وقريدات … اما بالصيف\nسهلاات وما يتعدوون الكتاب\n\nراعي الموضوع خذ سي اي و انجلش احسن شي", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/106441/10", "user": "user5643", "ts": 1303193093000, "tid": 106441, "pn": 10}}', 1303193093000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p153403-ce201', 'stk-user2177', 'CE 201', 'info', '{"desc": "السلام عليكم @46@\n\n@46@ يا شباب اللي نزل عند الدكتور \\\\مطفى المنديل وأخذ Ce 201 معاه نرجو أن يفيدنا عن الدكتور من ناحية المياجر والكويزات وغيرها رجاء@66@ @66@ \\_\\_\\_\\_\\_\\_\\_\\_\\_\\_\\_\\_\\_\\_\\_\\_\\_\\_\\_\\_\\_\\_\\_\\_\\_\\_\\_\\_\\_\\_\\_\\_\\_\\_\\_\\_\\_\\_\\_\\_\\_\\_\\_\\_\\_\\_\\_\\_\\_\\_\\_\\_\\_\\_\\_\\_\\_\\_\\_\\_لا إله إلا أنت سبحانك إني كنت من الظالمين \\+\\+\\+\\+&&&\\+\\+\\+\\+ لا إله إلا الله و الله أكبر", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/55045/1", "user": "user2177", "ts": 1171921746000, "tid": 55045, "pn": 1}}', 1171921746000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p903716-ce201', 'stk-oddball', 'CE 201', 'info', '{"desc": "وعليكم السلام\n\nme205 مادة ممتعة وشيقة وحلوة ومثيرة\nالمذاكرة من الكتاب\nحاول تفهم المادة وتحل امثلة الكتاب والهومورك\nاللاب لازم تلبس بدلة\nلكن ممكن حق اللاب يتساهل\nانا اذكر يوم اخذتها ما كان يتساهل حقنا ولازم تلبس بدله لكن نشوف شعب ثانية فيهم طلاب مش لابسين الا ثياب\nce201 هذه المادة ما ادرستها لاني مش ساينس\nse301 مادة سهلة جدا جدا لكن من الصعب الحصول ع درجة حلوة\nطبعا تحل في الامتحان لكن التصحيح دقيق جدا لدرجة لو ما حطيت قوس يحاسبك عليه\nطبعا مدققين في التصحيح لاعلى درجة في هذه المادة لان المادة جدا سهلة\nstat319 حلوة المادة مائلة الى الصعوبة لو ماذاكرتها اول بأول\nدائما يحطون اسئلة الواجب من برا الكتاب لهذه المادة فتطلع نتايج الطلاب ممتازة اذا حلوا الواجب طبعا\nلكن لو حطوا الواجب من الكتاب فتلقى الحل في السولوشن مانوال وماراح يستفيد الطالب\nطبعا انا كنت احل الاسئلة اللي من برا حقت الواجب لوحدي وجبت في المادة A+\nاحمد ربك لو جابولك اسئلة واجب من برا\nولو كانت حق الكتاب وماجابوا من برا حاول انك تحلها من نفسك وماتغش لانها الطريقة الوحيدة لفهم المادة", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/110095/40", "user": "oddball", "ts": 1316276943000, "tid": 110095, "pn": 40}}', 1316276943000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p77962-ce201', 'stk-no0o0', 'CE 201', 'info', '{"desc": "السلام عليكم ورحمة الله وبركاته\n\nأخوكم مسجل مادة CE 201 هذا الصيف مع الدكتور شكري السنان ومررررررررره متضايق\n\nالماده سهله بس الدكتور مو عارف يوصلها لعقول الطلاب\nوالكتاب طبعا مافيه شي … نص الصفحه الدرس وعشرين صفحه تمارين منت فاهم فيها شي .\n\nأنا أطلبكم ياشباب الهندسه المدنيه الـ Soluition لهذه المادة.\n\nتكفوووووووووووووون …\n\nأخوكم no0o0", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ce/48210/1", "user": "no0o0", "ts": 1121518438000, "tid": 48210, "pn": 1}}', 1121518438000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1464080-ce201', 'stk-user8581', 'CE 201', 'info', '{"desc": "اذا تبي تخلي الصيف سهالات نزل الانجلش 214 مع الاسلامي مثل ما قال بوريان\nاذا انت تحس جدول 162 مب ثقيل عليك واذا نزلت الصيفي ناوي تذاكر وماتسحب\nفرايي نزل كورس متوسط مع الاسلامي في الصيفي … وهالكورس يكون من السفمور ومافيه لاب .\nمثلا CE201\nوهالرابط راح يفيدك لو بتنزلها في الصيف\nce 201 الصيف\nبالتوفيق", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/175383/20", "user": "user8581", "ts": 1481288748000, "tid": 175383, "pn": 20}}', 1481288748000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p747062-ce201', 'stk-user4392', 'CE 201', 'info', '{"desc": "اخوي بالنسبة لك نزل ce201 وما عليك من كلام الناس\nيا اخي تدري وش مشكلتنا الكبيرة ان الواحد يقول المادة صعبة او سهلة جزافا\nلابد انك تعرف وش محتوى المادة قبل ماتنزلها لان المادة السهلة عندي صعبة عندك والعكس صحيح\nفلذلك اقول لك هذه المادة من اولها الى اخرها تتكلم عن قانون واحد الا وهو ان مجموع القوى عند اي محور تساوي صفر ومن بعدها تتفرع قوانين كلها ترجع لهذا القانون العام\n\nفهي مادة تحتاج فهم ولا تحتاج كثير حفظ نزلها عند القحطاني او المنديل وبتدعي لي ان شاء الله\n\nرأيي يعتبر وجهة نظر قابلة للقبول او الرد", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/99360/58", "user": "user4392", "ts": 1292758094000, "tid": 99360, "pn": 58}}', 1292758094000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p474017-ce201', 'stk-scatter', 'CE 201', 'srcU', '{"html": "مافي أسئلة هوم ورك<br><br>المفروض أن دكتوركم هوه اللي يعطيكم الأسئله<br><br>​<span data-fid=\"stk-f474017-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f474017-0": {"name": "Syllabus.doc", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/be45b3d10abc67d580d7fb9112e7a1b2edebd29821768a81eb25cb6f27c8e3cc"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ce-201/78764/2", "user": "Scatter", "ts": 1255297301000, "tid": 78764, "pn": 2}}', 1255297301000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p762539-ce201', 'stk-_hlali', 'CE 201', 'srcU', '{"html": "وعليكم السلام<br><br>الفاينل ان شاء الله راح يكون من تشابتر 6<br><br>الى تشابتر 10 وهذا السيلبس فيه الدروس المطلوبه<br><br>​<span data-fid=\"stk-f762539-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br>​<span data-fid=\"stk-f762539-1\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f762539-0": {"name": "CE201-Lecture Schedule.doc", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/8dd655273e906976760a24a1c17640889dde7265ff47cf00e3af14484c0d8431"}, "stk-f762539-1": {"name": "CE201-102_arif[12]0.doc", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/f01b249c45332b8cd7b890e61173c34327c4e579bc39804d21332b012f260c63"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ce201/100639/2", "user": "_HLALI", "ts": 1294889431000, "tid": 100639, "pn": 2}}', 1294889431000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1202185-ce201', 'stk-ll_m_ll', 'CE 201', 'srcU', '{"html": "Engineering Mechanics – Statics 12th Edition (SI Units); by: R. C. Hibbeler)<br>هذا اسم الكتاب<br><br>السيلابس بالمرفقات<br><br>​<span data-fid=\"stk-f1202185-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f1202185-0": {"name": "ce 201-121 Syllabus.doc", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/2246a6d60373d2bfe7b1e1c80890fb2876ae1fd6d81331e3dbd064e7ca896d34"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ce-201/142274/2", "user": "ll_M_ll", "ts": 1364089465000, "tid": 142274, "pn": 2}}', 1364089465000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p900160-ce201', 'stk-alroosi', 'CE 201', 'srcU', '{"html": "تفضل…<br><br>تلاقيها في المرفقات…<br><br>بالتوفيق 👍<br><br>​<span data-fid=\"stk-f900160-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f900160-0": {"name": "CE-201-06Course Syllabus T011.doc", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/6f3bf912a6576a42afac9ff61f165192eb9df42fb0d56d6a4c8b1bf4259ccf06"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ce201/111913/2", "user": "AlRoosi", "ts": 1315861012000, "tid": 111913, "pn": 2}}', 1315861012000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
