INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1140362-ce201', 'stk-user8521', 'CE 201', 'srcU', '{"html": "ما أدري اذا كانت سيلابوس الـce تفرق من دكتور لثاني<br>لكن هذي حقتي (دكتوري شكري السنان)<br><br>​<span data-fid=\"stk-f1140362-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f1140362-0": {"name": "ce 201-121 Syllabus.doc", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/2246a6d60373d2bfe7b1e1c80890fb2876ae1fd6d81331e3dbd064e7ca896d34"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/136343/3", "user": "user8521", "ts": 1355446048000, "tid": 136343, "pn": 3}}', 1355446048000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user4636-ce201', 'stk-user4636', 'CE 201', 'doc', '{"docs": [{"id": "stk-dr-m69876", "n": "Dr. Khalid Al-Shammari", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "تعقيب + اضافة على ردي السابق\n\nمع الاسف بديت اكره الكلاس معه 😦\n\nصراحه صار كم موقف لاحظت فيه انه يبدي راحته اكثر من مصلحة الطالب\n\nومصلحة الطالب عنده ماتسوى ريال جنب راحته ومصلحته\n\nاعطيكم بعض المواقف\n\nالموقف الاول كان ميجر 2 في يوم الاثنين بالليل وكان عندنا ايضا كلاس ماث بالصبح\n\nقال لنا يوم السبت ((اللي هو قبل الميجر بيومين)) عندكم كوز على ماتيريال الميجر\n\nقلنا له يادكتور خلها الاثنين احسن عشان نصير على كل حال مخلصين ماتيريال الماده للميجر\n\nيصير ناخذ كوز يوم الاثنين الصباح يكون مراجعه لنا وبالليل الميجر\n\nقال لا انا مو فاضي اصحح!!\n\nقلنا طيب مو لازم تصحح حط لنا بس السلوشنز بالموقع والتصحيح مو مشكله بعدين\n\nقال لا انا ماقدر عندي اسئلة طلاب الاوريا ومدري ايش\n\nيعني فرقت هاليومين!!\n\nالموقف الثاني عندنا حنا يوم اوف اللي هو بعد ميجر 2 ماعطانا اياه للحين وقال بعدين بعطيكم اياه احسن\n\nالمهم امس قال لنا عندكم كوز يوم الاربعاء القادم\n\nثم قال تبون الاوف حقكم يوم السبت؟؟\n\nقلنا لا خلها الربوع وعطنا الكوز يوم السبت عشان الثلاثاء عندنا كوز ce201 وكثير طلاب بالكلاس عندهم هالماده\n\n((وكان كثير من الطلاب اذا ماكان كل اللي بالكلاس موافق على انه الكوز يكون يوم السبت بدال الاربعاء))\n\nوقال لا الكوز يوم الاربعاء\n\nقال واحد من الشباب يادكتور حنا عندنا ميجر الثلاثاء خل الكوز يوم السبت عشان نذاكر خميس وجمعه\n\nرد عليه الدكتور انت حليت الهوم وورك؟؟ قال الطالب ايه\n\nقال اجل خلاص تعتبر فاهم الماتيريال مايحتاج تراجع!!\n\nيعني بالنسبه للمره الاولى اوكي ممكن تكون مشغول بأسئلة السنة التحضيريه لكن هالمره ماعندك شي وش بيضرك تخليه يوم السبت 😦\n\nانقهرت صراحه حسيت انه مايهتم ابدا لظروف طلابه اهم شي دام هالشي اسويه ويريحني خلاص اسويه ولا علي منهم 😦\n\nالدكتور باختصار اخلاق وحبيب ويتفاهم معاك ويتكلم معاك ماقول شي عن اخلاقه\n\nلكن مشكلته انه مايهتم بمصلحة الطلاب صراحه وحاط براسه انك انت يالطالب فاضي للمادة وماعندك غير الماث 😦\n\nوبالنسبة لتصحيح المياجر صراحه يعطيك بالملي ومايتساهل مثل بعض الدكاتره\n\nحتى بعض الاسئلة عندي يكون خطأ بالناتج النهائي بس واللي قبل كله صح يروح يخصم علي درجتين عشان الناتج النهائي ((جزء منه)) خطأ قهر صراحه 😦", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p746889-ce201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/khalid-al-shammari/69876/29", "user": "user4636", "ts": 1292733676000, "tid": 69876, "pn": 29}}]}', 1292733676000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user5643-ce201', 'stk-user5643', 'CE 201', 'doc', '{"docs": [{"id": "stk-dr-f98555", "n": "Dr. Salah U. Al-Dulaijan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "التحضير يوميا\n\nطريقة الشرح :\n\nيكتب نوت عالسبوره ويستخدم اسلايدات استخدام بسيط جدا\nالنوت حقه ممتاز … كله اولد اقزامز وهذا مهم لـ ce201 ce203\nطبعا شرح ما يحتاج شريييييح\n\nالكويزات :\nمن الهوم ورك 🙂\n\nالمياجر:\nكومن\nالفاينلات : كومن\n\nالقريد النهائي:\n\nانسان حق قريد … غير انه يدف . غير انه شرييييييييح … ويعطي (( هينت )) عن االاختبارات\n\nالصوت:\nواضح\nإضافات :\nمدرس متواضع … اخلااق عاليه … حبيب ومتساعد\n\nالله يوفقه وين ماراح , احسد قسم الهندسه المدنيه على هالدكتور الرائع", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p745276-ce201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-salah-u-al-dulaijan/98555/3", "user": "user5643", "ts": 1292520864000, "tid": 98555, "pn": 3}}]}', 1292520864000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user3630-ce201', 'stk-user3630', 'CE 201', 'doc', '{"docs": [{"id": "stk-dr-f98559", "n": "Dr. Hamdan Naser Al-Ghamedy", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ce 201-092\n\nالتحضير :ورقة تمر واذا خلصت يشيك على العدد يعني بالعربي الطلاب ما فيهم ثقة وبن امك تفكر تحضر غيرك\nطريقة الشرح : سلايدات ويجيب ام النوم وبن ابوك لو فيك خير تفكر ما تنتبه معه يناديك باسمك ويقعد يحقق معك\nالكويزات :نصيحه لوجه الله اذا خيركم تبون كويزات ولا هووموركات اختاروا كويزات لان الهوومورك هوه مألفه ويبغاك 4 ساعات تشتغل عليه اسبوعيا\nالمياجر:كومن\nالفاينلات :كومن\nالقريد النهائي:F بكل جدارة واظن هو المدرس الوحيد في الجامعة يستحق هذا\nالصوت:عادي\nإضافات : يجمع الطلاب انه اسوأ مدرس في الجامعة\nتخيلوا ولد عمي دفعة 95 يوم سمع اسمه قلي علوم اخس من علومنا الحالية", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p782671-ce201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-hamdan-naser-al-ghamedy/98559/6", "user": "user3630", "ts": 1296992348000, "tid": 98559, "pn": 6}}]}', 1296992348000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ippoo-ce201', 'stk-ippoo', 'CE 201', 'doc', '{"docs": [{"id": "stk-dr-f98561", "n": "Dr. Naser Abdul-Rahman Al-Shayea", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ce 201 ترم 143\nالتحضير : على حسب الوقت يحضر وما عنده مشكلة مع التاخير\n\nالشرح : جدا سيئ يشرح الكونسبت الاساسي ويعطيك امثلة تحلها بنفسك\n\nالواجبات : كل شابتر بواجب تقريبا 10 واجبات احيانا لو طلبت منو تاجيل الموعيد يقبل\n\nالكويزات : سهل جدا جدا تقريبا 5 كويزات\n\nالمياجر والفاينل : متوسطه نوعا ما\n\nالتصحيح : جدا سيئ يحاسب على كل كبيره وصغيره واشاء اصلا هو ما شرحها واذا عندك خطا في بداية السؤال ما يبني عليها فغالبا تاخذ في السؤال\n3/25\n\nتقييم : D+\n\nبشكل عام لا تعتمد على شرحو خليك ع السلف استدي احسن لك والمياجر والفاينل لا تنسى ولا نقطه", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1426587-ce201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-naser-abdul-rahman-al-shayea/98561/5", "user": "ippoo", "ts": 1441007127000, "tid": 98561, "pn": 5}}]}', 1441007127000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-saqr-ksa-ce201', 'stk-saqr-ksa', 'CE 201', 'doc', '{"docs": [{"id": "stk-dr-f98563", "n": "Dr. Muhammad H. Al-Malack", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "أخذت معاه ce201 أظن في 091\n\nالتحضير :\nيحضر بالإسم\nطريقة الشرح :\nيقرأ السلايدات, وأمثلة الكتاب بحيث يعطيك الأساسيات فقط و تحسك فاهم لكن لما تجي تحل سؤال تعرف أن ما معك سالفة\nالكويزات :\nلا يوجد\nالمياجر:\nكومن\nالفاينلات :\nكومن\nالقريد النهائي:\nC+\nالصوت:\nمتوسط إلى خافت\nإضافات :\nما أنصح فيه في هذي المادة غيرها ما أدري عنه خصوصا أن الأسئلة فيها أفكار كثير و هو زي ما ذكرت ما يحل إلا أمثلة الكتاب, بالإضافة إلى أنه في الكلاسورك نقص على كل غياب درجة كاملة", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p749298-ce201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-muhammad-h-al-malack/98563/3", "user": "Saqr-KSA", "ts": 1292966743000, "tid": 98563, "pn": 3}}]}', 1292966743000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abdelaziz-ce201', 'stk-abdelaziz', 'CE 201', 'doc', '{"docs": [{"id": "stk-dr-f98563", "n": "Dr. Muhammad H. Al-Malack", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CE 201 - 151\n\nالتحضير :\nنهاية كل محاضرة.\nوكل غياب عليه خصم ( -0.5 % )\n\nطريقة الشرح :\nشرحه ممتاز وواضح عليه الخبرة\nمن السلايدات ويستخدم السبورة كثير 👍\n\nالكويزات :\nكثيييرة نسيت كم حوالي 13 كويز - يأخذ أفضل 8 فيهم .\n\nالمياجر:\nكومن 4 أسئلة .\nميجر 1 : سهل جداً حاول تكون قريب من الفل مارك ( الافرج 82% )\nميجر 2 : صععب جداً ( الافرج 47 % اتوقع )\n\nالفاينلات :\nكومن\nللأسف الشديييد جداً صارت المادة Comprehensive في ترم 151\nالفاينل جاء من حيث لانعلم جداً طوييييل 😦\n\nالقريد النهائي:\nأعطي الدكتور A\n\nالصوت:\nواضح ولغته سهله ومفهومة.\n\nإضافات :\nالدكتور شرييح بطل\nممكن كثرة كويزاته تقروش لكن في النهاية أنت المستفيد\nالتصحيح ما اتوقع هو اللي يصحح فيه عنده Grader وكانت الدرجات تتأخر بشكل مب طبيعي 🤠\nاتوقع انه افضل الموجودين\nلكن عيبه كلاساته كلها في الصباح الباكر 😢 😢\n\nموفقين 🌹", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1437826-ce201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-muhammad-h-al-malack/98563/24", "user": "Abdelaziz", "ts": 1451787483000, "tid": 98563, "pn": 24}}]}', 1451787483000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ahm2d1-ce201', 'stk-ahm2d1', 'CE 201', 'doc', '{"docs": [{"id": "stk-dr-f98563", "n": "Dr. Muhammad H. Al-Malack", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Ce 201 | Term 182 :\n\nالتحضير : يحضر من اول كلاس في الترم الى اخر كلاس.\nالشرح : جيد وفيه اشياء ممكن تفهمها منه وفيه اشياء لا بس بشكل عام يمشي الحال بس مشكلته ايام يجيب النوم.\nالكويزات : اول كم كويز كانت سهله بس بعدها ضغطنا في الكويزات ولا امدانا نذاكر لها فا صرت ادخل وانا مو فاهم زين بس عطاني درجه في الكلاس ورك ما توقعتها ابداً الله يجزاه خير.\n\nبشكل عام ومقارنة بالدكاترة الباقين اشوفه نفس مستوى الباقين", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1508984-ce201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-muhammad-h-al-malack/98563/29", "user": "Ahm2d1", "ts": 1556231591000, "tid": 98563, "pn": 29}}]}', 1556231591000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-khdsa2022-ce201', 'stk-khdsa2022', 'CE 201', 'doc', '{"docs": [{"id": "stk-dr-f98563", "n": "Dr. Muhammad H. Al-Malack", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "اسم الدكتور : الملاك\nالمادة: Ce201\nBY WHATSAPP\nالفصل الدراسي: 191\nبنود التقييم ⬇️⬇️⬇️\n\nالتحضير : يحضر يومياً تقريباً، ويحضر اخر اللكشر ويسمح بالتأخير لو تجي بعد نص ساعه من بداية اللكشر ما يقولك شي.\nطريقة الشرح : يشرح نوتات لين يخلص من الكونسبت وامثلة الكتاب ثم يبدأ يعرضلنا اسئلة اختبارات قديمة ويحلها معنا، صراحة مرررررة مفيد من ناحية الاولد بروبلمز اللي يرسلها لما بالبلاكبورد ويعرضها لنا بالكلاس بعد.\nالكويزات : غالباً كويزاته تجي من الاسئلة اللي يرفعها لنا بالبلاكبورد لين عرفنا طريقته ثم غيرها. كويزاته متفاوته مرة سهل ومرة صعب ومرة وسط، عموماً عطانا ١٢ كويز واخذ افضل ٨.\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: صراحة الدكتور يستاهل A من وجهة نظري، طبعاً ماكنت من اللي يجون بدري دايم متأخر عن الكلاس بس اذا جيت وحسيت قاعد يقول معلومة مهمه انتبه معه ويفيدني بس ماكنت معتمد عليه، اخذت الكورس سيلف ستدي، بس ابداً ماقصر معي بالكلاس وورك، عطاني بونص درجة عشان ماغبت الا ٣ مرات بالترم( نظامه ٣ غيابات وبعدها يبدأ يخصم) وفيه طلاب اللي ولا غياب بالترم عطاهم بونص ٣ درجات بالكلاس وورك، عموماً فوق الدرجة ذي لقيته زايدني بعد، دكتور يدلع درجات الله يسعده. ناهيك عن القريد النهائي اللي اخذته، مجموعي كان على حافة ال B+ يعني بعيد عن A وانصدمت انه عطاني A الله يسعده.\nالصوت: بداية الترم ضعيف نوعاً ما، بس بعده اشوف عادي وينسمع اغلب الوقت\nإضافات : اذا تبي قريد لايفوتك دكتور متعاون جداً الله يسعده، واذا تبي تنتظم معه وتركز وتجي بدري احسن واحسن وبتستفيد منه كثيييير، انا مشكلتي انه كان اول كلاس بالجدول", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1518860-ce201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-muhammad-h-al-malack/98563/31", "user": "Khdsa2022", "ts": 1578313149000, "tid": 98563, "pn": 31}}, {"id": "stk-dr-f118680", "n": "Dr. Shakhawat Chowdhury", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "BY WHATSAPP\nاسم الدكتور : Chowdhury\nالمادة: Ce 201\nالفصل الدراسي: 191\nبنود التقييم ⬇️⬇️⬇️\n\nالتحضير : يحضر يومياً في الغالب بعد مرور نصف ساعة من الكلاس يمرر ورقة التحضير لكن احيان يحضر بالاسامي ما يعطيك ليت على التأخير و يقبل ميك اب.\nطريقة الشرح : يتكلم شوي عن الموضوع بشكل عام و القوانين ايضاً الي راح تحتاجها عشان تحل على الدرس وبعدين يحل على السبورة و في الغالب يعطي وقت حتى الطلاب يحلون السؤال ويسمع اجاباتهم وايضاً يجبرك على الحل معه شرحة جداً عادي لكن المادة مهي صعبة بالسلف ستدي\nالكويزات : اعطانا 14 كويز تقريباً يعني كل اسبوع كويز في بداية السمستر قال بيحذف اسوأ كويزين وحذفلنا اسوأ اربع كويزات وفيه ممكن كويزين اعطانا فيها فل و اعطانا واحد هوم كويز و بالاخير زبط جميع الطلاب في الكلاس وورك\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: A\nالصوت: واضح الى حد ما\nإضافات : المادة مو صعب تجيب فيها قريد بس تحتاج تحل فيها مسائل ويفضل انك تحل الهوموركات بنفسك طريقت مذاكرتي افهم الكونسيبت اما من الكتاب او سلايدات الاسطى و بعدين اشوف طريقة حل الامثلة واشوف هل فهمي كان جيد او لا وبعدها ابدأ احل البرنسبل بروبليمز كاملة و اذا كان عندي وقت حليت اسئلة الواجب المتعلقة بالدرس و اذا حسيت اني فاهم خلاص اوقف حل اما لو حسيت عندي نقص احل زيادة وقبل المياجري اراجع الدروس و الي احس اني مضيع فيه احل عليه و بعدين اروح احل مياجر وهذا كان وضعي و بالتوفيق للجميع مادة ممتعة", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1518863-ce201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-shakhawat-chowdhury/118680/17", "user": "Khdsa2022", "ts": 1578313249000, "tid": 118680, "pn": 17}}]}', 1578313149000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-sake-ce201', 'stk-sake', 'CE 201', 'doc', '{"docs": [{"id": "stk-dr-f98563", "n": "Dr. Muhammad H. Al-Malack", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CE 201 - 192\n\nالتحضير : في اخر المحاضرة عن طريق الاسامي ، مرن جدا بالتحضير وماعنده مشكلة تجي متأخر بسبب انك جاي من مبنى بعيد\n\nطريقة الشرح : يقرا سلايدات بوربوينت ويشرحها شرح خفيف ويفصل احيانا عالخفيف بالسبورة ، حتى مع الامثلة يقراها محلولة ونادر يستخدم السببورة في حلها ، وحتى لما يستخدم تحس تضيع وياه لانه تركيزه الكلي عالكلام مو السبورة ، شرحه سيئ\n\nالكويزات : بنفس صعوبة المياجر وغالبا كويزاته يجيبها من الامثلة اللي يرفعها عالبلاك بورد اللي هي اساسا اسئلة مياجر ، لكن بالاخير قام يجيب اسئلة من برا عشان عرفنا من وين يجيب اسئلته\n\nالمياجر : كومن\n\nالصوت : واطي واذا جلست بعيد مابتسمع شي\n\nاضافات : الدكتور طيب واخلاق لكن احيانا يقهرك بردوده وتصرفاته في فترة الاونلاين ، طريقة تحضيره بالاونلاين هي اخر المحاضرة يصور الحضور ، ولكن يظل 10-20 دقيقة بعد نهاية المحاضرة عشان يشوف من خرج ومن لا ،، بالنسبة لي مجملا الدكتور سيئ وخليه اخر خيار لك واذا انجبرت تاخذ عنده فخذ ، المادة مهمة و سهلة وسلف ستدي", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1521839-ce201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-muhammad-h-al-malack/98563/32", "user": "SAKE", "ts": 1588879233000, "tid": 98563, "pn": 32}}]}', 1588879233000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-m_nd_m-ce201', 'stk-m_nd_m', 'CE 201', 'doc', '{"docs": [{"id": "stk-dr-f98564", "n": "Dr. Hamad Ibrahim Al-Abdul Wahhab", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "T161 - CE201\n\nالتحضير : ورقة تمر على الطلاب… ماعنده مشكلة تحضر و تختبر مع سكشن ثاني… حذف غيابين ثلاث لكل طالب\n\nطريقة الشرح : الشرح ببساطة أنه يفتح السلايدات و يشرح الكونسبت و بعدين يبدأ يحل المسائل مع الطلاب… يمسك الطلاب واحد واحد كل واحد لازم يشارك بالحل و ابن امك سرح 🤠\nو يستخدم السبروة لرسم الـFree Body Diagram و كتابة المعدلات\n\nالكويزات : عطانا كويزات كثير حوالي 8 تقريبا و حذف أسوء اثنين\n\nالمياجر: -\n\nالفاينلات : -\n\nالقريد النهائي: أتركه لكم\n\nالصوت: واضح جدًا\n\nإضافات :\nإيجابيات:\nشرحه ممتاز و منظم جدًا\nحبيب و محترم جدًا\nفاهم زين و إذا مافهمت شي روح له بالأوفس أورز بفهمك\nمهتم جدًا بالطلاب و يحاول يتعاون معنا و يحفزنا قدر المستطاع\nيحذف أسوء كويزين و يحذف غيابين كما سبق و ذكرت\nمعطي الطلاب مهلة يراجعون أوراق المياجر إلى آخر يوم دوام\n\nسلبيات:\nغير متعاون من ناحية موعد تسليم الهوموركات\nشديد شوي و صعب التعامل معه (اذكر مرة سجلني غياب بنفس اليوم اللي أخذنا فيه كويز… و رحت كلمته أكثر من مرة و جبت له الكويز كإثبات لكن مافي فائدة… بالأخير حذفه بعد عناء طويل)\nماعنده أبجريد مادري إذا المشكلة من عنده ولا من الديبارتمنت\nبعض المرات ما يسمح لك تسأل\n\nكويزاته و سلايداته و بعض الملفات المهمة:\nCE201 - Hamad | تحميل\n***أتمنى إعلامي في حالة عدم الملف\n\nملاحظة بخصوص التصحيح/ مو هو اللي يصحح الكويزات ولا هو اللي يصحح كل الميجر… الكويزات يصحح طالب ماستر و الميجر عبارة عن مجموعة أسئلة كل دكتور يضع سؤال واحد و هو اللي مسؤول عنه و مادري أي كل سؤال تابع لمن\n\nأي معلومات أخرى بخصوص الكورس تلقونها بموضوع التقييم", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1466941-ce201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-hamad-ibrahim-al-abdul-wahhab/98564/7", "user": "M_nd_m", "ts": 1485290730000, "tid": 98564, "pn": 7}}]}', 1485290730000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user10843-ce201', 'stk-user10843', 'CE 201', 'doc', '{"docs": [{"id": "stk-dr-f98564", "n": "Dr. Hamad Ibrahim Al-Abdul Wahhab", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CE-201 Term:181\n\nالتحضير: ورقة تمر عالطلاب، وعلى حسب متى ماتذكر وزعها، يمكن بالبداية يمكن بنص المحاضرة يمكن بعد مانطلع يتذكر وينادينا نوقع 🙂\nمايقول شيء للمتأخرين ويسمح بالحضور في شعبة ثانية.\n\nالشرح: يفتح سلايدات القسم بعدين يتحلطم شوي لانها مغطية عالسبورة بعدين يشرح فكرة الدرس. يمسك الطلاب واحد واحد ويخليهم يحلون الامثلة معاه. شرحه جدا ممتاز ولكن \" احيانا \" مايجاوب عالأسئلة ويقول فكر فيها واجاوبك المحاضرة القادمة 🙂\nطريقته ممتازة، محد يقدر يسرح في كلاسه الكل يشارك ومنتبه معاه، افضل من انه يقعد يتكلم ٥٠ دقيقة واحنا نطالع فيه.\n\nالكويزات: سهههلة جدا، يعطينا كويز بشكل اسبوعي، الحين الاسبوع التاسع اخذنا ٧ كويزات 🙂\nلكن كويزاته سهلة، سؤال واحد ومجرد تنتبه معاه وتحل مثالين من الكتاب تجيب ١٠. يجيب أسئلته من “Problems” وغالبا تكون من اول ٥ اسألة.\n\nنصيحة: تعال لكلاسه وانت محضر للدرس، عشان مايطقطق عليك اذا ماجاوبت وعشان تستفيد من المشاركة معاه.\nملاحظة: الصورة اللي فوق يبدو انها قديمة جدا، الدكتور كبير بالسن ( يارب مايقرأ ).🙂", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1501776-ce201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-hamad-ibrahim-al-abdul-wahhab/98564/8", "user": "user10843", "ts": 1541159692000, "tid": 98564, "pn": 8}}]}', 1541159692000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user5712-ce201', 'stk-user5712', 'CE 201', 'doc', '{"docs": [{"id": "stk-dr-f98567", "n": "Dr. S. Al-Senan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "أخذت معه CE 201 - صيف 103\n\nالتحضير :\nيحضر كل يوم ، وفي بداية الكلاس ، وما يشتهي اللي يتأخر\n\nطريقة الشرح :\nأنا أخذت معه مادة CE 201 ومن زمان ما درسها ، بس ماشاء الله عليه كان محضر لنا ملفات word لكل التشباتر ، وكان يقرأ من السلايدات ويأشر بالليزر فقط ونادراً ما يكتب شيء على السبورة ، وكان يحط تمارين كثيرة في سلايداته بس كان يقراها قراءة ويبين فكرتها فقط\nأنا كنت أشوف الفكر بس وأروح الغرفة وأتكتك على المسائل\nيعني شرحه بشكل عام يعتبر متوسط وبعض الأحيان يختبص وهو يشرح ، بس تقدر تسيطر على المادة لو كنت عنده ، وكان يقول لو عندكم سؤال في الكتاب أو حتى الواجب تعال وأنا أحله لك وأفهمك السؤال ، رحت له المكتب كذا مرة وما قصر\n\nالكويزات :\nلا يوجد كويزات ، لأن المادة كانت في الصيف ولا في مدرس ثاني معه ، فضبط السليبص مثل ماهو يبقى\n\nالمياجر والفاينلات:\nطبعاً هو اللي كتب المياجر كلها ، وكتبها بطريقة تختلف عن اللي كان معمول عادة في ce 201 ، كان القسم يحط 4 أسئلة فقط في كل ميجر وكلها كتابة وعلى كل سؤال 25% وكل مدرس يحط سؤال ويصححه ، أما هذا الدكتور حط 13 أو 14 سؤال ومشكلين : بعضهم صح وخطأ وبعضهم كتابة خطوات وكان الميجر متوسط وفيه بعض الأسئلة صعبة واجد وبعضها تافهة حيل .\nومن ناحية التصحيح للمياجر أذكر أنه كان شديد في التصحيح وما يرضى تناقشه في توزيع الدرجات ولا يرضى يزيد درجات\n\nالقريد النهائي:\nأعطيه B ، لأن شرحه كان حليو ، بس أسلوبه في الشرح كان غريب وسريع ، لكن مستحيل تحتاج مصدر ثاني غير سلايداته لأنها كافية ووافية\n\nإضافات :\nشرحه زين بس هو شايف نفسه وما يشتهي ياخذ ويعطي مع الطلاب واجد ، ومايرضى تناديه إلا دكتور أو بروفسور ، ولو قلت له أستاذ أو teacher ماراح يرد عليك\nإضافة إلى أنه ألغى كل كلاسات يوم الأربعاء من بداية الصيف إلى نهايته ، وكان يكنسل بعض الكلاسات على حسب المزاج ، ومع هذا كنا متقدمين على السليبص\n\nأنا اعتبره مدرس مقبول بالمقارنة مع مدرسين هالقسم لأن أغلبهم ماعندهم سالفة\nبس لو نزلت عنده شد على حيلك شوي/FONT]", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p893269-ce201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-s-al-senan/98567/8", "user": "user5712", "ts": 1314618842000, "tid": 98567, "pn": 8}}]}', 1314618842000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user8521-ce201', 'stk-user8521', 'CE 201', 'doc', '{"docs": [{"id": "stk-dr-f98567", "n": "Dr. S. Al-Senan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ce201\n121\nالتحضير : يحضر كل كلاس , وكذا مرة يغيب الطلاب اللي ما طبعوا النوت وجابوها معهم\nطريقة الشرح :شرحه لا بأس به , يشرح الكونسيبت ويحل أمثلة وهذا أشوفه كافي\nالكويزات : ما عنده كويزات\nالفاينلات والمياجر:كومن والتصحيح كذلك كومن\nالصوت: واضح\nإضافات :الدكتور حذف كلاس الاربعاء فصار ما فيه الا كلاسين بالاسبوع, فصار يحسب الغياب بغياب ونص , والكلاس وورك كله (20بالمية) كان عالهومووركات, ونصيحة حاول انك تقلل احتكاكك بالدكتور قدر المستطاع(انا رحت له للاوفيس مرتين بالسمستر وكنت مضطر وقتها) لانه الله يهديه فيه شوفة نفس وتحس انه وده يفتك منك ويزحلقك بأي طريقة", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1165122-ce201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-s-al-senan/98567/14", "user": "user8521", "ts": 1358376029000, "tid": 98567, "pn": 14}}]}', 1358376029000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user7045-ce201', 'stk-user7045', 'CE 201', 'doc', '{"docs": [{"id": "stk-dr-f98567", "n": "Dr. S. Al-Senan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "الدكتور هذا نزلت عنده قبل ترمين ce201\nاخلاقه وتعامله سيء\nلسببين ينظر لطالب بنظره دونيه مدري على وش\nوالثانيه لتعامله السيء مع الطلاب جيت عنده مره ابي اعرف الغياب قال لي ما لي دخل فيك انت ادرى بغياباتك قلت يادكتور ابي اتاكد لا يلحقني دي ان قال بالحرف الواحد اذا جاك دي ان بتشوفه في الترانسكربت بالله هذا تعامل\nشرحه عادي يشرح من السلايدات مع ان الماده محتاجه حل مسائل اكثر من الشرح\nيعطي مقالات للسلامه المدنيه واشياء ثانيه ويقول اقروها والكلاس الثاني يسألك فيها ولازم يحرجك اذا ما قريتها او يعطي كوزات ابو خمس دقايق عليها\nسحبت عليه وتابعت شروحات من اليوتيوب افضل منه بالف مره\nالتاخير يدقق احيان واحيان يمشي\nالتحضير اول الكلاس واذكر مره من المرات ما عدد الا اسماء ثلاث طلاب وهم اصحاب الغياب الكثير يا حبيبي وش ذا النظام يا تحضر الطلاب كلهم يا تخليهم كلهم اما تستقعد على بعض وتترك بعض لا\nالصوت جيد جدا\nاحسن مافيه يكنسل كلاسات يعني خلانا نداوم سبت واثنين وحذف الاربعاء يقولك بياخذ ربع ساعه زياده تعويض ليوم الاربعاء لكن في النهايه الكلاس مايعدي 45-50 دقيقه\nكويزات مافيه الكلاس وورك كله عالحضور و الهومورك\nتلاحظ فيه عجاز ولا يحب يتعب نفسه مع الطالب يعني تساله يا يسفل فيك مثل انت كيف خلصت الاوريا ,ما تعرف تتكلم انجليزي ,كيف نجحت\nولا يعطيك ذيك النظره ويسحب عليك\nعلى كل حال كان من اسوء الدكاتره اللي مرو علي في الجامعه بالرغم انه دفني قريد\nالقريد النهائي F\nلا تنزل عنده الماده محتاجه شرح وهو من جنبها واذا تحس انك بتدبر عمرك في الشرح\nالله يعينك على تعامله", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1245138-ce201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-s-al-senan/98567/17", "user": "user7045", "ts": 1373671839000, "tid": 98567, "pn": 17}}]}', 1373671839000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-hexane-ce201', 'stk-hexane', 'CE 201', 'doc', '{"docs": [{"id": "stk-dr-f98568", "n": "Dr. Alfarabi M. Sharif", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "بسم الله\n\nأنا نزلت معه ce 201 في سمستر 101\n\nالتحضير: في بداية السمستر كان يحرص على التحضير لكن بحسب ما أذكر, تقريباً في نص السمستر ما عاد صار يحضر\nو لكن إنتبه مره من المرات حضر بعد ما شاف الغياب كبير\n\nطريقة الشرح: حلوة و سلسة و يبسط لك الفكرة\n\nالكويزات: ما أذكر إنه عطانا كوز واحد و لكن بالمقابل كان يعطينا هوم ووركات كثيرة وصلت ل 22 هوم وورك\n\nالمياجر : كومن\n\nالفاينلات: كومن\n\nالقريد النهائي: A\n\nالصوت : واضح\n\nإضافات:\n\n1) الدكتور ما شاء الله عليه حبوب و أخلاقه عالية و يهتم بفهم الطلاب للدرس\nو لكن زي ما تفضل mr:3lol إن الدكتور مبطي عن المادة فكان أحياناً يعلق في بعض المسائل فتاخذ منه وقت أطول من اللازم علشان كذا أنا أعطيته a وإلا هو يستاهل +a.\n\n2) هي 3 كلاسات بس هو خلاها كلاسين مدة كل كلاس ساعة و عشر دقائق.\n\n3)الهوم ووركات حقته مهمه جداً. لكل هوم وورك ينقي له تقريباً من أسئلة الشابتر 6 أسئلة و أحياناً أكثر. تحلها كلها بفهم راح تستفيد بشكل كبييييير في المياجر و في الفاينل. بس مو تحلها لحالها ثم تخش الإختبار لأنه ممكن يعطيكم هوم وورك ما يغطي جميع الأفكار.\nفقبل الإختبار إبدأ بأسئلة الهوم وورك و الوقت الباقي خله للأسئلة الثانية و للأولد إكزام.\n\nموفقين", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p779868-ce201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-alfarabi-m-sharif/98568/3", "user": "HeXaNe", "ts": 1296514043000, "tid": 98568, "pn": 3}}]}', 1296514043000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user2967-ce201', 'stk-user2967', 'CE 201', 'doc', '{"docs": [{"id": "stk-dr-f98569", "n": "Dr. Mustafa Al-Mandil", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ce 201 - 091\n\nالتحضير : في اول الكلاس\nطريقة الشرح : من سلايدااات او اوراق شفافه اللي توضع ع جهاز ماعرف اسمه هع\nالكويزات : ناسيها\nالمياجر: نظام المادة كومون\nالفاينلات : ^^^\nالقريد النهائي: ممتاز\nالصوت: واضح\nإضافات : مشكلته يبسط لك الماده وتنخرش بالاختبارات لانه يعطيك دائما امثله سهله\n\nاعذروني ع هالتقييم لاني والله ناسيه\n\nوموفقين", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p744089-ce201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-mustafa-al-mandil/98569/2", "user": "user2967", "ts": 1292339214000, "tid": 98569, "pn": 2}}]}', 1292339214000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-harry_potter-ce201', 'stk-harry_potter', 'CE 201', 'doc', '{"docs": [{"id": "stk-dr-f98569", "n": "Dr. Mustafa Al-Mandil", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Ce 201 - 101\nالتحضير : اول الكلاس بعد 3 دقايق\nالشرح : يبسطلك افكار الكتاب و يشرحها بكل سهوله اللي يميزه انه يشرح بالعربي لا اكثر و لا اقل يشرح بالسلايدات و الجهاز ابو اوراق شفافه\nمره شرح على السبوره و طلع الشغل الصح\nاضافه : لا تسأله سؤال غبي و الله تروح وطي و هذا من اشد عيوبه عصبي\nالكويزات : بوب كويزز و هذا عيب فيه ثاني\nالهوم وركات : كل اثنين التسليم اول الكلاس ما سلمت 0 كبر وجهك 🙂\nالمياجر: كومن\nالفاينل : كومن\nالصوت : 10/10\nاللي عقدني القريدر حقه لا يمكن تتفاهم معاه و يعطيك يا 2 او 10/10 😦\nالتقييم : B+", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p774322-ce201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-mustafa-al-mandil/98569/3", "user": "harry_potter", "ts": 1295993187000, "tid": 98569, "pn": 3}}]}', 1295993187000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user6719-ce201', 'stk-user6719', 'CE 201', 'doc', '{"docs": [{"id": "stk-dr-f98569", "n": "Dr. Mustafa Al-Mandil", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "يعتبر من أفضل دكاترة القسم…أعرف كثير طلاب خذوا عنده من مختلف الدفعات والتخصصات(ce,me,che) كلللهم يمدحونه…\nاللي أعرفه عنه يدرس ce 201 فقط…\nوإنه يشرح بالعربي+كثير مرات يكون الكوردنيتار(منسق المادة)+يعطي همووركات مرتبة ويعلّق الحلولها على مكتبه وكثير مرات تكون مفيدة في المياجر…\n\nإذا قدرت تنزل لا تتردد…دائما شعبته تقفل على طول", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p782143-ce201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-mustafa-al-mandil/98569/6", "user": "user6719", "ts": 1296948755000, "tid": 98569, "pn": 6}}, {"id": "stk-dr-f98586", "n": "Dr. Omar Saeed Baghabra Al‑amoudi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "عمر العمودي\n\nكنت قد كتبت عن الدكتور عمر العمودي قبل أقل من سنة من الآن:\n\nبالنسبة للعمودي أنا منزل عنده هالترم وصراحة ما أنصح فيه أبدا…لأسباب كثيرة\nالشرح وطبيعة الكلاس:\nأولها وأهمها زي ما قال naruto 26 ما يهتم بالشرح كثير يشرح بالكثير أول 10 أو 15 دقيقة…\nأهم شي عنده أنه يحل أكبر عدد من المسائل والمشكلة أنه يجيبها من طبعات الــce 201 القدييييمة (يوزعها في أوراق على الطلاب) والمصيبة أن كل مسائل الكتاب تغيرت بالكامل… يعني حتى إذا حاولت تفهم معاه بالكلاس وبعدين تحل المسائل بنفسك بالبيت ما تقدر…\nالأخلاق: هو صراحة طيب وحبوب وعادل في تعامله مع الطلاب بس فيه غرور شوي (غرور وليس تكبر)…\nيعني يجيك أحيانا (مو كثير حتى أكون منصفا) يحب يتكلم عن نفسه ويحكي عن إنجازاته والمؤتمرات اللي حاضر فيها وكيف إنه كان أحسن واحد 😐…لكنه يتمتع بخفة ظل لابأس بها\n\nخلاصة القول خذ عند المنديل أو الفارابي أو القحطاني…\nوإذا ما قدرت وقدر الله عليك ونزلت عند العمودي حاول إنك تسأله كثير لين تتأكد من إنك فهمت وتتابع معاه أول بأول\n\nملاحظة مهمة جدا: أنا قيمته في كورس الــce 201…يعني تقييمي لطريقة الشرح في هذا الكورس ويمكن ما يكون لها أي علاقة في الكورسات الثانية…\nوإذا كان غير جيد في 201…قد لا يكون بالضرورة كذلك في الكورسات الأخرى", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p783059-ce201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-omar-saeed-baghabra-al-amoudi/98586/2", "user": "user6719", "ts": 1297049033000, "tid": 98586, "pn": 2}}]}', 1296948755000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-montadhar-ce201', 'stk-montadhar', 'CE 201', 'doc', '{"docs": [{"id": "stk-dr-f98569", "n": "Dr. Mustafa Al-Mandil", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "درسني ce201 سمستر 111\n\nالتحضير : بداية الحصة و حتى لو جيت متأخر يحضرك في النهاية و الميك أب عنده زي الكيك\nطريقة الشرح : ممتااااااااازة جددددددداً و خصوصاً بعد ميجر ون لأن متيريال ميجر ون كانت كروس برودكت و دوت برودكت و مع ذلك شرحها زين و لكن مو مثل متيريال ميجر تو و الفاينل\nالكويزات : بوب كويزز و هذا عيبه الوحيد\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: A+++++\nالصوت: واضح و ما يشرح إلا بالعربي هع هع\nإضافات : الدكتور محترم جداً و أخلاق و يرحب فيك لما تروح المكتب و يمزح بالفصل و دمه خفيف بس فيه نقطتين ما عجبوني غير الكويزات، قبل لا تسأله تضرب أخماس بأسداس لأني سألته أكثر من مرة و أحرجني، و الشي الثاني أنه يتأخر في وضع القريد و ما تشوفه إلا في الترانسكريبت.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p971789-ce201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-mustafa-al-mandil/98569/11", "user": "montadhar", "ts": 1327167823000, "tid": 98569, "pn": 11}}]}', 1327167823000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-black_light-ce201', 'stk-black_light', 'CE 201', 'doc', '{"docs": [{"id": "stk-dr-f98575", "n": "Dr. Maher A. Bader", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "أخذت معاه ce201\n\nالتحضير : يومي\n\nطريقة الشرح : مملة, وتجيب النوم, زي ماقال “nobleman” معاة قلم الليزر وهو جالس على الكرسي يشرح بالقلم…ماتحس انه مهتم بالمادة…يدرس عشان يشغل وقته فقط (واضح ان عنده بزنس خاص فيه)\n\nالكويزات : سهلة إذا تحل الهوموورك أو حتى الأمثلة بس\n\nالمياجر: كومن\n\nالفاينلات : كومن\n\nالقريد النهائي: D+\n\nالصوت: عادي\n\nإضافات : الدكتور حبوب وأخلاقة طيبة, لكن اذا كنت تدور شرح ماراح تلاقيه عنده…فعلاً كرهني بالمادة الي احبها…الحمدلله اني طلعت بقريد حلو لأني كنت معتمد على الله ثم الكتاب…بس كنت أشيل هم الكلاس بشكل غير طبيعي.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p940831-ce201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-maher-a-bader/98575/6", "user": "Black_Light", "ts": 1322762171000, "tid": 98575, "pn": 6}}]}', 1322762171000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-banyan-ce201', 'stk-banyan', 'CE 201', 'doc', '{"docs": [{"id": "stk-dr-f98576", "n": "Dr. Abdul - Hamid J. Al - Tayyib", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ce 201 في الصيف\n\nالتحضير\nيوميا عن طريق ورقة تسجل اسمك والايدي وتقدر تحضر خاويك\n\nطريقة الشرح\nبااايخة من دون مبالغة … يومياا يعطيناا كويز ويحله ع السبوورة واحيانا مايمديه يحله لانه بطيء في الشرح الله يحفظه واحيانا يخطئ في الحل فكنت احضر عشان اخذ الكويز وانقشه من المانيول سليوشن والتسليم يكون في الكلاص اللي بعده وبصراحة كنت شخصيا ما اعتمد عليه في الشرح\nمرة سالته سؤال وتوهق مسكين ولفق حاله والحمدلله اني سالته وماكان جمبنا احد من الطلاب عشان ماينحرج\n\nالمياجر والفاينل كانوا نوعا ما سهل الى متوسط\n\nالصوت يجيب النوم ويتكلم بالبطيء\n\nاضافات\nالدكتور محترم واخلاقه عاليه وهااااااادي", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p747137-ce201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-abdul-hamid-j-al-tayyib/98576/3", "user": "Banyan", "ts": 1292764886000, "tid": 98576, "pn": 3}}]}', 1292764886000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-_918-ce201', 'stk-_918', 'CE 201', 'doc', '{"docs": [{"id": "stk-dr-f98581", "n": "Dr. Shamshad Ahmad", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ce 201\n\nالتحضير يوميا ويحقد عالمتاخرين\n\nطريقة الشرح : يطفي اللمبات … و يشغل الراديو\n\nمايستخدم الطبشور … توصيله للمعلومة سيء جدا جدا\n\nكريف هوم وركز\n\nانسان حاقد رغم انه يظهر الطيبه\n\nمافي امل ياجل شغله\n\nالكوزات والهوموركات كلها محسوبه عليك\n\nالقريد النهائي F+\n\nابعدد عنه ولا بتحس انك منزل كورسين مو كورس واحد", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p851618-ce201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-shamshad-ahmad/98581/10", "user": "_918", "ts": 1307909960000, "tid": 98581, "pn": 10}}]}', 1307909960000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-civil_engineer1-ce201', 'stk-civil_engineer1', 'CE 201', 'doc', '{"docs": [{"id": "stk-dr-f98586", "n": "Dr. Omar Saeed Baghabra Al‑amoudi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Ce 201\n\nالتحضير : بداية الكلاس وما يحب التأخير\nطريقة الشرح : ماهو شريح مررة لكنه يحل اسئلة لين مايدوخ راسك\nالكويزات : 5-6 كويزات وسهلة ومافيها صعوبة يعني مذاكر فل مارك\nالمياجر:كومن\nالفاينلات :كومن\nالقريد النهائي:b+\nالصوت:واضح\nإضافات : الدكتور هذا ينفع للي يحضر أول بأول لأنه يحل مسائل كثيرة ويحاول يجيب اغلب التركات اللي تجي بالاختبار … يحب طلاب السيفيل ويركز عليهم … بالكلاس وورك متساعد اتذكر انا هومووركاتي فل مارك وكويزاتي فل مارك وعطيني درجة بونص عشان ماعندي ولا غياب وكان دايم يسأل اسئلة تحدي اذا جاوبت صح +1 واذا أخطأت-1 بالكلاس وورك وكان عندي +1 فصار مجموعي 17 من 15 و وعدني لو بقالي درجتين على قريد انه يعطينياه", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p940889-ce201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-omar-saeed-baghabra-al-amoudi/98586/4", "user": "civil_engineer1", "ts": 1322768685000, "tid": 98586, "pn": 4}}]}', 1322768685000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mtlinjawi-ce201', 'stk-mtlinjawi', 'CE 201', 'doc', '{"docs": [{"id": "stk-dr-f98586", "n": "Dr. Omar Saeed Baghabra Al‑amoudi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "درست عنده مادة ce 201 في الترم 111\n\nالتحضير : يومي، و مرات يعطي حصص إضافية، و مرات يلغي حصص، بعد المياجر يحذف بعض الغيابات. ما يحب التاخير\nطريقة الشرح : حل مسائل من الأوراق الشفافة\nالكويزات : كان يسالنا عن الطريقة الي نبغاها في الكويزات، قبل الاختبار الاول كان كل اسبوعين يعطينا ٣ كويزات دفعة وحدة ، بين الاختبار الاول و الثاني ما اعطانا ولا واحد، الا قبل الاختبار بليلة أعطانا ٣ كويزات ، رجعنا طلبنا منه كويزات قام يعطينا تيك هوم كويز من الاختبارات القديمة\nالمياجر: مشتركة من القسم\nالفاينلات : مشتركة من القسم\nالقريد النهائي: جيد جدا إلى ممتاز\nالصوت: واضح ( يعجبني يشرح بالعربي )\nإضافات : الدكتور أخلاق", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p974226-ce201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-omar-saeed-baghabra-al-amoudi/98586/5", "user": "mtlinjawi", "ts": 1327592716000, "tid": 98586, "pn": 5}}]}', 1327592716000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-iahmed015-ce201', 'stk-iahmed015', 'CE 201', 'doc', '{"docs": [{"id": "stk-dr-f98586", "n": "Dr. Omar Saeed Baghabra Al‑amoudi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "# TERM 121 - CE201: Statics\n\nالتحضير :\nنهاية كل كلاس، ويحفظ الطلاب من اول كلاسين ماشاء الله عليه.\n\nطريقة الشرح :\nيوزع اسئلة مع كل تشابتر ووظيفته يحلها ( ينقلها ) من الحل اللي عنده ، لا بأس فيه غالباً يجاوب على اسئلة الطلاب، انا ماكنت افهم منه كثير.\n\nالكويزات :\nفاشلة من الكتاب واحياناً من الاكزامبلز ، مالها اوقات محددة ولا عدد محدد ويحشرك قبل الاختبارات .\n\nالمياجر:\nكومون، ميجر اول سهل ، ميجر ثاني لّهب\n\nالفاينلات :\nسهل ووقت طويل\n\nالقريد النهائي:\nB\n\nالصوت:\nيشرح بالعربي\n\nإضافات :\nهوموركاته كثيرة بشكل خيالي.\nالدكتور ماعجبني، اذا لقيت احسن منه نزّل !\n( احضر ) + ( سلّم هوموركاتك ) + ( سلّم كويزاتك - بعضها بالبيت )\nولاحظ انه ضغط، يعني يكرفك باوقات صعبة دائماً مايعطي الكويزات الا قبل المياجر والفاينل.\n\n* مكتبه بعيد عند المسلخ + القريدر عنده كل شئ يعني لدرجة تسأله عن اي هوموورك اليوم يقول اسأل القريدر تقوله الكويز عندي شئ فيه يقول شوف القريدر ، يعني الشيء الوحيد اللي تتابعه فيه الغيابات.\n\n* يخليك تحضر كلاس بالليل اذا غاب يوم عشان مؤتمر وكذا\n* زي ماقال واحد قبلي انه يعقد المادة\n\n< اعظم حسناته كان باقيلي 1.15 على القريد ودفنّي اياها،\nمدري هو دف كامل الكلاس ولا بس انا ، الله يعطيه العافيه عليها >", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1164007-ce201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-omar-saeed-baghabra-al-amoudi/98586/6", "user": "iAhmed015", "ts": 1358157988000, "tid": 98586, "pn": 6}}]}', 1358157988000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-yasserxz-ce201', 'stk-yasserxz', 'CE 201', 'doc', '{"docs": [{"id": "stk-dr-f98586", "n": "Dr. Omar Saeed Baghabra Al‑amoudi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ce201--171\n\nالتحضير : كل يوم بكل ما تحمله الكلمة من معنى.\n\nطريقة الشرح :كل شايتر يوزع ورق تكون تحتوي على اسالئة ويحلة كم واحد منهم على الصبورة .-- ويعرض الورقة بالالة الي تعرضة على البروجكتر. واذا كنت انت تركز معه بتطلع بفايدة من كل كلاس ،، واشوف ان المادة سلف ستدي وخصوصا ان لها مقاطع كثييير باليوتيوب . هذا شررريح (\nhttps://www.youtube.com/watch?v=5kLu\\-T6Z7KA\n) واكتب باليوتيوب statics شرح بيطلع لك ماقطع وااااجد\n\nالكويزات : ما كانت كثيرة عكس باقي المدرسين الي يعطون كوز كل اسبوع واشوفه مرة متعبة . بس معه عطانا ثلاث كوزات تقريبا ومستواة تقربا زي الامثلة حقت الكتاب.\n\nالمياجر و الفاينلات : كومن بس صعبة شوي وطبيعي تحصل افرج الميجر 30 من 100 -_- .\n\nالقريد النهائي: B\n\nالصوت: عربي .\n\nإضافات : يعيب الدكتور ان شرحة كان ممل شوي والي يبي يحضر ويجلس ورى بينشب له ويحفظ الوجية بسرعة.\nطبعا المادة كلها رتن والمصحح حق العمودي على وقتنا مان ممتاز يمش وخصوصا بالواجبات لانه الواجبات اسبوعية وطويلة ،، بس المشكلة انه يمكن يتغير.\n\nالمدرس طيب\n\n* وسامحوني على القصور.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1493748-ce201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-omar-saeed-baghabra-al-amoudi/98586/8", "user": "yasserXz", "ts": 1528163537000, "tid": 98586, "pn": 8}}]}', 1528163537000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ittihad7997-ce201', 'stk-ittihad7997', 'CE 201', 'doc', '{"docs": [{"id": "stk-dr-f98586", "n": "Dr. Omar Saeed Baghabra Al‑amoudi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "درست عنده CE201 ترم 191\nالتحضيري يومي ورقة يوزعها واحيانا يدقق ويعطي اول ٣ غيابات مجاني بدون خصم\n\nطريقة الشرح : مملة بصراحة يستخدم اوراق شفافه قديمة ويكتب على السبورة ، والدكتور يقول انه يحب الاسئلة من الطلاب لكن اذا سألته ( تقريبا ) يعصب ويقول تونا شرحناها !!\n\nالكويزات : طبعا هذي للاسف سلبية بالدكتور … مافي كوزات بوقت الكلاسات ، يعطي ٣ كلاس تست وتكون قبل ميجر ١ و٢ والفاينل يعني فوق مو المياجر بالليل فوقه كلاس تست !!!! ،، لكن بالاخير اكرمنا بالكلاس وورك\n\nاضافات : الصوت واضح ويشرح باللغتين والدكتور مايحب احد يمسك الجوال بالمحاضرة.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1518629-ce201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-omar-saeed-baghabra-al-amoudi/98586/9", "user": "ittihad7997", "ts": 1577936193000, "tid": 98586, "pn": 9}}]}', 1577936193000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user11848-ce201', 'stk-user11848', 'CE 201', 'doc', '{"docs": [{"id": "stk-dr-f98586", "n": "Dr. Omar Saeed Baghabra Al‑amoudi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "بنود التقييم : CE 201 - 191\n\nالتحضير : يمرر ورقة بشكل شبه يومي\n\nطريقة الشرح : طريقته قديمة بالشرح ولكن يبدأ يفهمك الكونسبت بالعربي ثم ينتقل حل الاسئلة من نوتاته ويتأكد بعد كل سؤال من فهم الطلاب\n\nالكويزات : ماعنده كويزات , 3 كلاس تست كل واحد قبل الاختبار بأسبوع تقريبا\n\nالمياجر: كومون\nالفاينلات : كومون\nالقريد النهائي: B+\nالصوت: واضح جدا\nإضافات : الدكتور كريم في التصحيح جدا لدرجة اعطاني 3 درجات زيادة على احد الاسئلة بس لأن الحل مرتب , سالفة الكلاس تست له ميزه ان يريحك من الكويزات كل اسبوع وتصير تدرس كأنه ميجر لكن العيب انه يكون بفترة المياجر الثانية وبالليل, الدكتور حبيب وبشوش ونفسيته حلوه\nالدكتور مظلوم ببعض التقييمات.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1525998-ce201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-omar-saeed-baghabra-al-amoudi/98586/11", "user": "user11848", "ts": 1601630159000, "tid": 98586, "pn": 11}}]}', 1601630159000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-a_b_d_u_l_l_a_h-ce201', 'stk-a_b_d_u_l_l_a_h', 'CE 201', 'doc', '{"docs": [{"id": "stk-dr-f98590", "n": "Dr. Husain Jubran Al-Gahtani", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "السلآم عليكـم …\n\nأنا حاليا آخذ كورس ce 201 مع هذا الدكتور\n\nحتى الآن أجده ممتااااااااز\n\nشرحه حلو ويتفاعل مع الطلاب و يحاول يوصل المعلومة بأسلوبه\n\nكويزاته سهلــــــــــــــــــــــــــــــــــــــــــــــــــــــة\n\nمن ناحية التحضير هو يقول انه بيحضر بس انه يتغاضى عن الموضوع أحيانا\n\nبس كلآسه ما يتفوت يخلص بسررررعة\n\nمن ناحية الصوت : واضح و لغته جميلة جدا\n\nالمياجر و الفاينل : كومون\n\nالقريد النهائي : بالانتظار\n\nاعطيه a\n\nأنصح به في الـ 201 بقوة\n\nجووود لك", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p744889-ce201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-husain-jubran-al-gahtani/98590/3", "user": "A_B_D_U_L_L_A_H", "ts": 1292446332000, "tid": 98590, "pn": 3}}]}', 1292446332000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user6661-ce201', 'stk-user6661', 'CE 201', 'doc', '{"docs": [{"id": "stk-dr-f118679", "n": "Dr. Mohammed H. Essa", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ce 201 - ترم 121\n\nالدكتور شرحه ممتاز ومتعاون مع الطالب بشكل عام …\n\nكل اسبوع (كويز وهوموورك) …\n\nيشرح بالسلايدات وسلايداته جدا مفيدة وكافية لإيصال الفكرة …\n\nافضل دكاترة القسم تعاوناً بالكلاس وورك …\n\nهالمادة بقدر ما تحل مسائل قد ما تحصل … يعني الدكتور مهمته يعطيك الفكرة والباقي عليك !\n\nانصح فيه …\n\nبالتوفيق 🌹 …", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1164865-ce201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-mohammed-h-essa/118679/3", "user": "user6661", "ts": 1358314379000, "tid": 118679, "pn": 3}}]}', 1358314379000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mohamed.ali-ce201', 'stk-mohamed.ali', 'CE 201', 'doc', '{"docs": [{"id": "stk-dr-f118679", "n": "Dr. Mohammed H. Essa", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ce 201 - ترم 122\nالتحضير… كل كلاس و احيانا يمشي لك 5 دقايق تاخير\nالشرح… عن طريق سلايدات و اذا كان فيه شيء يحتاج توضيح يشرحه على السبوره, لو سألته عن شي بسيط يجاوبك ما يسحب عليك مثل بعض الدكاتره\nالكوزات و الهوموركات… كوز و هومورك كل اسبوع تقريبا, و اسألة الهوموركات مهمه\nالمياجر و الفاينل… كومون وكل دكتور يصحح سؤال, و تصحيحه جيد\nالصوت… واضح\nالأخلاق… الصراحة ان الدكتور يحرجك بأخلاقة العالية متفهم و متعاون و بشوش مع الطلاب الله يجزاه خير\nالقريد النهائي… +A\nاضافات… الصراحة الدكتور ما يتفوت", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1320305-ce201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-mohammed-h-essa/118679/11", "user": "Mohamed.Ali", "ts": 1389970999000, "tid": 118679, "pn": 11}}]}', 1389970999000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abo_yazeed6-ce201', 'stk-abo_yazeed6', 'CE 201', 'doc', '{"docs": [{"id": "stk-dr-f118679", "n": "Dr. Mohammed H. Essa", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "الله يجزاه خير ,دكتور من أفضل الدكاترة الي درسوني في الجامعة.\n\nمتعاون جدا ,شرحه ممتاز وعنده سلايدات جيدة يشرح منها “لكنها ما تغني عن الكتاب”,يعطيك كل أسبوع كويز وهومورك ,حسسه أنك مهتم بالمادة وجيب درجات كويسة في المياجر وابشر بدرجة طيبة في الكلاس ورك.\n\nجاني وانا داخل اختبر الفاينل لمادته ce 201 ,وقالي لا تخاف من الكلاس ورك عطيتك درجة كاملة فيه,مع اني والله ساحب على الهوروركات من ميجر1 وجايب العيد في كذا كويز ,لكني مبدع في المياجر+دايم اشارك معه لأن المادة ممتعة جدا وسهلة لو تتابعها أول بأول.\n\nنصيحتي خله يعرفك من أول يوم باهتمامك ,وبإذن الله بتشوف كل خير.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1370436-ce201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-mohammed-h-essa/118679/12", "user": "abo_yazeed6", "ts": 1400934003000, "tid": 118679, "pn": 12}}]}', 1400934003000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user8890-ce201', 'stk-user8890', 'CE 201', 'doc', '{"docs": [{"id": "stk-dr-f118679", "n": "Dr. Mohammed H. Essa", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Ce 201 - 141\n\nالله يذكره بالخير ، لو ما يجي منه إلا طيبته يكفيك هالشيء.\nالدكتور طيب والكلاس وورك عنده بالمتناول وكوزاته سهلة، كان ما عندك مشكلة بال سلف-ستدي فـ نزلها معه وتبي تشوف أطيب دكتور يمكن يمر عليك بالجامعة.\nلكن أمثلته اللي يحلها شوي بدائية. ف انصحك تشتغل على نفسك شوي بالمادة لا تعتمد على سلايداته", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1432398-ce201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-mohammed-h-essa/118679/15", "user": "user8890", "ts": 1446883333000, "tid": 118679, "pn": 15}}]}', 1446883333000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mohammedj-ce201', 'stk-mohammedj', 'CE 201', 'doc', '{"docs": [{"id": "stk-dr-f118679", "n": "Dr. Mohammed H. Essa", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ce201 term 162\n\nالتحضير :نهاية المحاضرة ، ماشاء الله حفظ اسماءنا .\n\nطريقة الشرح : في البداية يشرح أهداف الدرس وتطبيقات عليه (في ايش يستخدم و الخ…) بعدها يشرح على السلايدات و بعض الأحيان يستخدم السبورة ، بعدها يعرض لنا مسألة و يطلب منا اننا نحلها ، بعدها يحلها قدامنا ، و يعرض لنا التريكات اللي ممكن يجيبنوها . شرحه اشوفه ممتاز كان يسهل علي المذاكرة كثير و بعض الأحيان خلاص اطلع فاهم 100% مدري شرحه خورافي مرره ولا الماده سهلة .\n\nالكويزات :متوسطة الصعوبة ، جاب واحد من الهومورك .\n\nالمياجر:--- مدري اذا هو اللي يصحح المياجر ولا لا بس حتى لو مب عارف تحل اكتب اي حاجه ،حاول و تجيك شويات درجات .\n\nالفاينلات :----\n\nالقريد النهائي:A+\n\nالصوت:واضح بس نطقه لبعض الكلمات غريب .\n\nإضافات :\n-الدكتور طيب و حبيب مرره .\n- لا يسمح باستخدام الجوالات .\nملف فيه سلايدات و اختبارات قديمة والخ… https://drive.google.com/open?id=0B6TWh2zgUBWTcTZydFQ4VXQ1WDg", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1474311-ce201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-mohammed-h-essa/118679/16", "user": "mohammedj", "ts": 1496326969000, "tid": 118679, "pn": 16}}]}', 1496326969000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-illusions-ce201', 'stk-illusions', 'CE 201', 'doc', '{"docs": [{"id": "stk-dr-f118679", "n": "Dr. Mohammed H. Essa", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CE201\nTerm 172\n\nالتحضير : يحضر كل يوم خصوصا بداية الترم نهاية الكلاس وماشاءالله خلال اسبوعين الى ثلاثة يحفظ اسماء الطلاب. ,واخبر انه الكلاس الي قبل الميجر ويوم الميجر ما كان ياخذ تحضير بس ما يقول انه ما راح ياخذ.\n\nطريقة الشرح : سلايداته , جميله جدا سلايداته ويجي منها بالاختبارات , وكان دايم يشرح سؤال بعدين يفتح سؤال بعده ويقول يلا حلوا هذا ويخلينا ابو خمس دقايق بعدين يحله فلازم تجيب عنده دفتر وحاسبة وقلم\n\nالكويزات : عطانا حول 13 كويز وقال لنا بداية الترم بياخذ اعلى ثمانية تقريبا. يحدد يوم بالاسبوع من ثاني او ثالث اسبوع تبدون تختبرون بهاليوم كل اسبوع الى نهاية الترم. يفيدك مررره اذا بتذاكر لكل كويز. اخبر عطانا كويز فيه سؤال قبل الميجر الاول بأسبوع ولما دخلنا الميجر كان فيه سؤال ريتن عليه حول 25 بوينت من الميجر يشبه مره طريقة سؤال الكويز, والفاينل اخبرعطانا كويز على المومنت والشير دياقرام كان مثلث مع مربع وكان صعب الصدق , ولما خلصنا الكويز شرحه لنا وأاكد علينا اننا نفهمه زين , ولما دخلنا الفاينل عقبها بأسبوع مدري اسبوعين كان فييه سؤال ريتن بالفاينل عليه 25 بوينت عن المثلث عشان كذا الدكتور عظيم وعارف وش المهم بالكورس\n\nالمياجر: كومن وصعععععععععععععععععععبة وافرجهم بالارض\n\nالفاينلات : كومن , انت وحظك وافرج المياجر ومود القسم ذاك الترم\n\nالقريد النهائي: A+\n\nالصوت: واضح\n\nإضافات : الدكتور عظييييم , من افضل الدكاتره الي درسوني بالجامعة , بكل بساطة شريح وبنفس الوقت يعرف وشو المهم بالكورس ووشو الي بيجيك بالميجر فيضبطك بسلايدات وشرح زي العسل الله يجزاه الجنة .\nالتأخير الى خمس دقايق ما يقول شي بعدها لا\nالكلاس وورك عنده سهالات واذا انت مهتم سهل تجيب فيه درجة عالية مرة\nالمادة القسم زفت وتقسيمة درجاته زفت فتحتاج والله لدكتور مثله فاهم وشو المهم وعارف للقسم زين , لان مع كل هذا ويالله تسلم منها هالمادة وتعدي.\nسلايداته للكونسبت عظيمة وامثلتها حلوة بس بعضها شوي سهلة اذا قارنتها بأسئلة القسم اذا بدا يطقطق لان مياجرهم ارجع واقول صععععبة , انا اشوف لو حليت سلايداته كلها بفهم وتدربت عن طريق حل الهوموورك بنفسك ممكن تجيب قريد حلو بالمادة.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1497858-ce201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-mohammed-h-essa/118679/18", "user": "ILLUSIONS", "ts": 1534416945000, "tid": 118679, "pn": 18}}]}', 1534416945000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user11264-ce201', 'stk-user11264', 'CE 201', 'doc', '{"docs": [{"id": "stk-dr-f118679", "n": "Dr. Mohammed H. Essa", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CE201 - 191\nالدكتور محمد حسين عيسى\n\nالتحضير : التحضير في وسط الكلاس، بالبداية ينادي بالأسماء بعدين يحفظكم كلكم (حرفيًا، حتى اللي ما يشارك) ويصير يحضر بالنظر. مدري عن التأخير بس أحيانًا يزعل منه.\nطريقة الشرح : سلايدات ويشرح منها، نادر ما يكتب على السّبورة لكن رغم هذا أشوف شرحه ممتاز جدًا ويوصّل المعلومة لك غصب. بنص الكلاس يخليكم تطلعون أوراق وتحلّون المسائل.\nالكويزات : الكويزات متوسّطة، مرات تصعب ومرات تسهل. لكن المشكلة مب في صعوبة الكويزات لكن في مواعيدها! الدكتور ما عنده مرونة أبدًا بالمواعيد وعادي جدًا يجي أول الأسبوع يقولك يلا ترا نهاية الأسبوع كويز دبّر نفسك، أضيف على هذا إنه ما يستخدم البلاك بورد للتنبيه على الكويزات، يعني لو كنت غايب أو مو منتبه راحت عليك. عمومًا كويزاته كثيرة وفيه فرصة للتعويض، اختبرنا 12 كويز وأخذ أفضل 8\nالمياجر: -\nالفاينلات : -\nالصوت: واضح وممتاز\nالقريد النهائي: A+++++++\n\n* الدكتور ممتاز جدًا وأخلاقه لا يُعلى عليها، في نص الترم راح تلقاه يعرفكم كلكم ويعاملكم مثل أبناؤه\n* ما يحب استخدام الجوال في المحاضرة\n* عيبه الكبير بالنسبة لي كان مواعيد الكويزات، لكن أمرها سهل إن شاء الله بالمتابعة", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1519028-ce201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-mohammed-h-essa/118679/20", "user": "user11264", "ts": 1578855626000, "tid": 118679, "pn": 20}}]}', 1578855626000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-guest-ce201', 'stk-guest', 'CE 201', 'doc', '{"docs": [{"id": "stk-dr-f118680", "n": "Dr. Shakhawat Chowdhury", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "191 CE201\nالتحضير : ورقة يمررها واحيانا يقرا يشيك\nطريقة الشرح : سلايدات ويحل اسئلة وشرحه سيء نوعا ما.\nالكويزات :ابثر ام ام امنا بالكوزات من الاسبوع الثاني اتوقع الين قبل اخر اسبوع يمكن 14 كوز\nالمياجر: كومون التصحيح مو هو الي يصحح فيه لجنة تصحيح\nالفاينلات : نفس المياجر\nالقريد النهائي: C وكثير فيه\nالصوت: عادي\nإضافات : اسلوب بيض واخلاق اسوء ومايتفاهم مع الطالب و ف الاوفس اور اخلاقه سيئة + مره قال الي عنده سؤال يسأل ويوم سألته قال انت ماتذاكر؟؟؟ ذاكر ذاكر ! طيب ليش تفتح باب الاسأله اذا مابتجاوب! , كانت تجربتي معاه سيئة جدا.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1521960-ce201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-shakhawat-chowdhury/118680/18", "user": "Guest", "ts": 1589156594000, "tid": 118680, "pn": 18}}, {"id": "stk-dr-f118679", "n": "Dr. Mohammed H. Essa", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Dr. Mohammed Hussain Essa’s Website\nبنود التقييم : ce 201 >>>192\n\nالتحضير : يحضر ف البداية و مايقول شي لو تاخرت بس مايحب تتاخر\nطريقة الشرح : يشرح عن طريق السلايدات لانها كومن للكل و فوقها يعطيك امثلة واقعية ويقولك الشي الضروري و الشي الي ماتحتاجة\nالكويزات : الكويزات كان متعاون معانا ف كل شييي متى نبيه و احيانا ياجل بعد و تصحيحه ع القريدر ماله شغل\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: AAAAAAAAAAAAAAAAA بطل AAAAAAAAA\nالصوت: واضح . المدرس سوداني اعتقد و لهجته واضحة\nإضافات :\nالمدرس حضرت له الكورس بعد ما حملته عند عبد الوهاب و حضرته حضوري و اونلاين بطططططططل و الله ان من دخلت الجامعة ماحد عجبني شرحه و تعاونه معك كطالب فناننن , احب اضيف مره ثانيه , اذا حصلت السكشن حقه وماخذته فانت خسرانن … +++ اي كورس جاي باخذه عنده", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1525005-ce201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-mohammed-h-essa/118679/21", "user": "Guest", "ts": 1598309575000, "tid": 118679, "pn": 21}}]}', 1589156594000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-stu2009-ce201', 'stk-stu2009', 'CE 201', 'doc', '{"docs": [{"id": "stk-dr-f118680", "n": "Dr. Shakhawat Chowdhury", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "بنود التقييم :\nسمستر112-ce201\n\nالتحضير :\nيحضر يوميا وأحيانا بداية المحاضره وأحيانا بالنهايه…\nطريقة الشرح :\nيشرح على السبوره ويحل أمثله من السلايدات وطبعا بداية السمستر الى ميجر ون كان بطل…وبعدها صار ينقل الحل من السلايدات ويقعد يتكلم 😐…طبعا هذا اللي خلانا نخبص معاه بعد ميجر ون 😐\nالكويزات :\nكويزاته يمكن 13 كويز 🤪…طبعا اثنين منهم كانوا اكسترا كويز لأن السكشن كان جايبين العيد في الكويزات 🤠\nالمياجر:\nكومن\nالفاينلات :\nكومن\nالقريد النهائي:\nC+\nالصوت:\nواضح ولكن الأكسنت لك عليه\nإضافات:\nالدكتور خلوق جدا ويحاول يوصل المعلومه للطلاب…ويخليهم يسجلوا معاه بالنوت…ولكن للأسف طريقة شرحه ما تشجع الطلاب انهم يتابعوا معاه في المحاضره 😐…\nوأخيرا لا تسجل عنده اذا لقيت من هو معروف بأنه أفضل منه 🙂", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1076279-ce201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-shakhawat-chowdhury/118680/5", "user": "stu2009", "ts": 1344216656000, "tid": 118680, "pn": 5}}]}', 1344216656000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user10610-ce201', 'stk-user10610', 'CE 201', 'doc', '{"docs": [{"id": "stk-dr-f118680", "n": "Dr. Shakhawat Chowdhury", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CE 201 -181\n\nيا إلهي يبدو أنني تحت الضغط لأنني اول واحد يقيم الدكتور منذ فترة طويلة :speech_balloon: 🥊.\n\nطيب الدكتور في البداية حبيب وجلاد في نفس الوقت ! طبعا اولا التحضير ورقة تمر على جميع الكلاس ويعرف أسماء بعض الطلاب ( اللي يجلسون في الزوايا + طلاب التخصص + كذا واحد يعرفهم بالأسم, وفي نهاية الترم اذا جاء يوزع الكوزات يقول الاسم ويعرف راعيه يعني بيصير يعرف كل الكلاس ) .\n\nالشرح يعتمد على السلايدات حقته وهي حلوه الى حد ما فيها اسئلة جيدة لكن الحل موب دائما موجود لذلك لااااازم تكتب معه . وقبل الميجر أو الكوز يرفع لنا عالبلاكبورد اسئلة اولد اقزام أو اسئلة أسطورية اذا حليتها تقدر تحل بإذن الله اي سؤال لانها تكون شاملة جدا .\n\nالدكتور أصغر اولاده أكبر من كل اللي في الكلاس 😄 😄 لذلك دائما يقول لنا انتوا مثل أولادي ولازم أهتم فيكم , ( وهذا يتضمن أنه يشششد عليك اذا كنت ما تذاكر 😄) وأول كلاس يقول حنا فريق واحد انا ما أقدر اشتغل وحدي وانتم ما تقدرون تشتغلون وحدكم لذلك خلونا نتعاون , وفعلا تلاقيه يشيل همك ويحاول يساعدك كأنك ولده .\n\nالمادة تعتبر موب زب الماث متعود عليها هذي كذا شي بسيط بس طويل لذلك أنصحك تقرأ تقييم الكروس وتعرف كيف تذاكر من البداية . ( الكورس تراكمي تشابتر 2 بتستعمله في تشابتر 9 )", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1503899-ce201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-shakhawat-chowdhury/118680/16", "user": "user10610", "ts": 1545466442000, "tid": 118680, "pn": 16}}]}', 1545466442000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-dok116-ce201', 'stk-dok116', 'CE 201', 'doc', '{"docs": [{"id": "stk-dr-f118681", "n": "Dr. Md Arifuzzaman", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "درست عنده ce 201 في ترم 102\nالرجل طيب جداً جداً جداً ومتساهل بشكل كبير في التحضير ويقبل أي أعذار, أذكر أحد الشباب قله غبت لانو كان عندي اختبار وكنت بذاكرله ومسح له الغياب !\nلكن من ناحية الشرح فالشرح سيء جداً جداً جداً جداً , عدة أشياء أحس انو مو فاهمها وحتى لو كان فاهم مايقدر يوصل المعلومة نهائياً , ما أدري يمكن هذا بسبب انو كان أول ترم له ؟", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p974337-ce201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-md-arifuzzaman/118681/3", "user": "dok116", "ts": 1327616759000, "tid": 118681, "pn": 3}}]}', 1327616759000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user7462-ce201', 'stk-user7462', 'CE 201', 'doc', '{"docs": [{"id": "stk-dr-f118685", "n": "Dr. Muhammad S. Vohra", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "درسني ce201\nالتحضير :كل يوم لازم يحضر\nطريقة الشرح : على بور بوينت وهالشي ما اشوفه زين بالماده بس احيان يسوي هيلب سيشن عشان يحل مسائل فيها\nالكويزات : سهله\nالمياجر: كومون\nالفاينلات : كومون\nالقريد النهائي: b\nالصوت: الصوت واضح والاكسنت هندي واجهت مشكله معه بالبدايه بعدين تاقلمت\nإضافات : الماده كانت مهي صعبه تنفهم سلف ستدي بنسبة 80 بالميه لذا ماكنت مركز مره معه بس اذا ركزت اشوفه كويس والله يفهّم , والرجال جدا جدا جدا مؤدب ومحترم لدرجه كبييره", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1173352-ce201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-muhammad-s-vohra/118685/8", "user": "user7462", "ts": 1359532393000, "tid": 118685, "pn": 8}}]}', 1359532393000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user7794-ce201', 'stk-user7794', 'CE 201', 'doc', '{"docs": [{"id": "stk-dr-f151651", "n": "Dr. Wael Alhajyaseen", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ce201 - 131\n\nالتحضير :\nنهاية كل كلاس…و نادرا بالبداية …\nمتساهل بالتحضير… واحد كان يستحق dn لكن ساعدة .\n\nطريقة الشرح :\nأممم … كان يشرح الكونسبت بالبداية و بعدين يحل مثال متوسط الصعوبة …\nشرحة كويس نوعا ما … لكن طبيعة المادة “ce201” تحتاج جهد شخصي في الفهم … و خيال واااااسع…\n\nالكويزات :\nسهلة و كثيــــــــــــــــــــــــــــــــــــــرة.\n\nالمياجر: كومن و كانت متوسطة الى صعبة …والوقت ليس كافي لغير الدوافير…\n\nالفاينلات : كومن … وكان سهل الى متوسط والوقت كاااافي 🙂\n\nالقريد النهائي: b\n\nالصوت: واضح\n\nإضافات :\n* تقييمي لسمستر 131 … وهو كان يقول انه رح يتغير بالأترام الجاية خصوصا بالتحضير.\n*بالنسبة للـce201 , المادة سهلة بس يبيلها جهد شويتين و أنصح الطلاب بالموقع تبع الكتاب رح تلاقيه بأول الصفحات…\n* الدكتور أخلاق …لكن أحيان يتنرفز لو سألته كثير .\n…\nكل التوفيق 🌹", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1319088-ce201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/wael-alhajyaseen/151651/3", "user": "user7794", "ts": 1389704842000, "tid": 151651, "pn": 3}}]}', 1389704842000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user9929-ce201', 'stk-user9929', 'CE 201', 'doc', '{"docs": [{"id": "stk-dr-f152669", "n": "Dr. Mohammed Al-Osta", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "التحضير : يوميا بواسطة ورقة تمشي ويمديك تحضر خويك و هو يدري ان فيه بعض الطلاب يحضرون اخوياهم بس اذا شافهم تمادوا يطلبهم للمكتب ويطلب منهم ما يسووها مره ثانية واخر الترم يحذف كم غيب عن كل طالب\nطريقة الشرح :يشرح من سلايدات شرحه اعطيه 8/10\nالكويزات :كوزاته سهله اغلبها من مياجر سابقة واذا جت صعبة يساعد الطلاب في حلها او يعطيك فرصة تحل مع زملائك او يقول take home\nالمياجر: من المنسق (كل مدرس يحط سؤال)\nالفاينلات : من المنسق\nالقريد النهائي: ِA+\nالصوت: واضح ولغة جيدة واكسنت يمني بعض الاحيان\nإضافات : ادرس عنده ce 201 حاليا هو دكتور حصل عليها 2013\nيمني الجنسية حبوب ولطيف للغاية متساعد ومتفهم للطلاب لدرجة ما تتصورها واذا صحح الميجر يزيد الطلاب اذا راجعوه وتحديدا السؤال الي يحطه\nولا يفوتك اذا ناسبك الوقت الماده سهله لكن انتبه تهمل لانه طيب ومتسامح لانها بتروح عليك وهو يدف الطلاب في الكلاسوورك", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1433292-ce201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/prof-mohammed-al-osta/152669/10", "user": "user9929", "ts": 1447517819000, "tid": 152669, "pn": 10}}]}', 1447517819000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user10775-ce201', 'stk-user10775', 'CE 201', 'doc', '{"docs": [{"id": "stk-dr-f152669", "n": "Dr. Mohammed Al-Osta", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "بنود التقييم :\nCe201\n163\nالتحضير :\nأول الكلاس و ما يتجاوب مع التأخير (على كلامه بس يمكن يمزح غالبا)\nطريقة الشرح :\nيشرح لك على لين تفهم النقاط كلها و هو فاتح السلايدات\nالكويزات :\nمتوسطة الصعوبة كلها من الكتاب تقريبا.\nالمياجر:\ncommon\nالفاينلات :\ncommon\nالقريد النهائي:\nA+\nالصوت:\nواضح جدا و بتكلم العربية غالبا\nإضافات :\nيستقبل بحفاوة في المكتب و طيب لأبعد حد.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1480668-ce201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/prof-mohammed-al-osta/152669/13", "user": "user10775", "ts": 1505917138000, "tid": 152669, "pn": 13}}]}', 1505917138000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-21m-ce201', 'stk-21m', 'CE 201', 'doc', '{"docs": [{"id": "stk-dr-f152669", "n": "Dr. Mohammed Al-Osta", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CE201-T211\nالدكتور محمد الاسطى\nالتحضير : يحضر نهاية كل كلاس ويزعل على المتأخرين\nطريقة الشرح : يشرح من سلايداته فيها امثلة وفيها اولد اقزامز وأفكار حلوة ومتنوعة وتغني عن الكتاب\nالكويزات :متوسطة اغلبها من السلايدات او الهوم ورك\nالمياجر: كومن\nالفاينلات :كومن\nالقريد النهائي:A++++++++++++++++++++++++++++++++++++++++++ ووالله انها ماتكفي ولو بالجزء البسيط من حقه\nالصوت: واضح جدا ومفهوم\nإضافات : دكتور بمعنى الكلمة كامل في كل شيء ماشاء الله عليه خلق وشرح مايمشي من السؤال الي يتأكد انك فاهم كل شيء ماعنده مشكلة يعيد الفكرة مليون مرة اهم شيء انت تفهم ويستخدم السبورة بالشرح ويحل من بداية الكلاس لنهايته وكلاسه ممتع جدا ماكنت اتوقع بستمتع بالمادة زي ما انا مستمتع فيها حاليا ومرن جدا في الواجبات والكويزات ياما اجلها لمصلحة الطلاب. وبضو في الكويزات شوي ويقوم يحل عنك من كثر مايفصل ويشرح طريقة حل السؤال والله كلمة دكتور اقل من حقه من افضل الدكاترة بالجامعة والله اذا مادرست عنده مادة CE صدقني فاتك كثيرولو تقدر تبني عليه الجدول او تبعص جدولك عشانه ؟ والله يستاهل.\n\nوالللللللللله الله يسعده وين ماراح", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1532717-ce201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/prof-mohammed-al-osta/152669/17", "user": "21M", "ts": 1636631630000, "tid": 152669, "pn": 17}}]}', 1636631630000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-_91110-ce201', 'stk-_91110', 'CE 201', 'doc', '{"docs": [{"id": "stk-dr-f176818", "n": "Dr. Faisal Mukhtar", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CE 201 - 162\nالتحضير :\nيوميا , يتساهل جدا جدا مع المتأخرين\nطريقة الشرح :\nيشرح من السليدات ويحل بعض المسائل على السبوره\n\nالكويزات : من أسئلة الهومورك نفس الأرقام\n\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: A\nالصوت: واضح وعالي\nإضافات :\nالدتور فيصل أول مرة يدرس CE 201 هذا الترم , لكن الوضع كان كويس معاه\nشرح كويس وأخلاقه عالية ويحب الأسئلة في الكلاس\nمتعاون جدا في الاوفس اور , وحريص على مصلحة الطالب", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1474181-ce201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/faisal-mukhtar/176818/2", "user": "_91110", "ts": 1496155669000, "tid": 176818, "pn": 2}}]}', 1496155669000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-the_rival-ce201', 'stk-the_rival', 'CE 201', 'doc', '{"docs": [{"id": "stk-dr-f178250", "n": "Dr. Saheed Adekunle", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "بسم الله الرحمن الرحيم\n\nفصل الاونلاين 201\nCE201\nلتحضير : من البلاك بورد بشكل تلقائي\n\nطريقة الشرح : من السلايدات ويكتب عليها باستخدام قلم\n\nالكويزات : كومن وكله خيارات\nالمياجر: كان مد وكله خيارات\nالفاينلات : كومن و خيارات\nالقريد النهائي: A\nالصوت: ممتاز\nإضافات :\nالدكتووور مرة طيب… كل مرة نسأله عشان يؤجل الكويز . يقبل ولا يقول لا…\nصراحة. يا إنه طيب وسوا لنا قروب واتس ولا يحجر لنا و يسجل كل المحاضرات لنا… لكن من طيبته وطيبة دكتورين غيره سمحوا بالكاميرا الامامية مما أدى أن بعض الناس يغشون ويرتفع الأفرج ونلقم قريدات نازلة…", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527789-ce201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/saheed-adekunle/178250/4", "user": "The_Rival", "ts": 1610302227000, "tid": 178250, "pn": 4}}]}', 1610302227000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user12042-ce201', 'stk-user12042', 'CE 201', 'doc', '{"docs": [{"id": "stk-dr-f178250", "n": "Dr. Saheed Adekunle", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CE201 term 201 (online)\nCE203 term 203 (online)\n\nالتحضير : تلقائي بلاكبورد+يبدا الخصم بعد الغياب الثاني بس ما يعلمكم على اساس انه من اول غياب\nالتصحيح : هو ما صحح الا هومورك في ce201 وكان مره رهيب بالتصحيح ما يدقق مره وce 203 كان طالب يصحح .\nالواجبات : كومن + مره تخليك متمكن من الكونسبت (يحذف اسوء واجب)\nالكويزات : الاسئلة الي يجيب جدا تهيئك للميد والفاينل (خيارات) (ce201,203)(يحذف اسوء كويز )\nالميد: كومن (ce201,203)\nالفاينلات : كومن (ce201,203)\nالشرح : ايش اقول بس ‘ مره بطل في الكورسين الدكتور (شريح) ‘ ركز معه بس ومن عندي قريد يبيض الوجه.\nالتعامل : اخلاق وعسل جدا وينكت ومتساهل معنا لابعد الحدود لدرجة ياخر كويز او هومورك.\n\nنزل معه وبس", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1531212-ce201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/saheed-adekunle/178250/5", "user": "user12042", "ts": 1628819060000, "tid": 178250, "pn": 5}}]}', 1628819060000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
